const fs = require('fs')
const path = require('path')

const arquivos = [
  ["lib/api/responses.ts", "import { NextResponse } from 'next/server'\nimport { ZodError } from 'zod'\n\nexport const ok = (data: unknown) =>\n  NextResponse.json({ status: 'success', data }, { status: 200 })\nexport const created = (data: unknown) =>\n  NextResponse.json({ status: 'success', data }, { status: 201 })\nexport const notFound = (message = 'N\u00e3o encontrado') =>\n  NextResponse.json({ status: 'error', message }, { status: 404 })\nexport const unauthorized = () =>\n  NextResponse.json({ status: 'error', message: 'N\u00e3o autorizado' }, { status: 401 })\nexport const forbidden = () =>\n  NextResponse.json({ status: 'error', message: 'Sem permiss\u00e3o' }, { status: 403 })\nexport const conflict = (message: string, modificationNum?: number) =>\n  NextResponse.json(\n    { status: 'error', message, modification_num: modificationNum },\n    { status: 409 }\n  )\nexport const badRequest = (message: string) =>\n  NextResponse.json({ status: 'error', message }, { status: 400 })\n\nexport const serverError = (err: unknown) => {\n  if (err instanceof ZodError) {\n    return NextResponse.json(\n      {\n        status: 'error',\n        message: 'Dados inv\u00e1lidos',\n        errors: err.errors.map(e => ({\n          field: e.path.join('.'),\n          message: e.message,\n        })),\n      },\n      { status: 400 }\n    )\n  }\n\n  const message = err instanceof Error ? err.message : String(err)\n\n  // Erro de duplicata PostgreSQL (unique_violation)\n  const pgCode = (err as any)?.code ?? (err as any)?.cause?.code\n  if (pgCode === '23505') {\n    return NextResponse.json(\n      { status: 'error', message: 'J\u00e1 existe um registro com este nome.' },\n      { status: 409 }\n    )\n  }\n\n  if (message === 'UNAUTHORIZED') return unauthorized()\n  if (message === 'FORBIDDEN') return forbidden()\n  if (message === 'TENANT_NOT_FOUND') return notFound('Tenant n\u00e3o encontrado')\n  if (message === 'USER_NOT_IN_TENANT') return forbidden()\n  if (message === 'USER_INACTIVE') return forbidden()\n\n  console.error('[sistematiza.erp]', err)\n  return NextResponse.json(\n    { status: 'error', message: 'Erro interno do servidor' },\n    { status: 500 }\n  )\n}\n"],
  ["components/layout/Sidebar.tsx", "'use client'\nimport Link from 'next/link'\nimport { usePathname } from 'next/navigation'\nimport {\n  BarChart3, Users, Boxes, ShoppingCart, DollarSign,\n  ChevronRight, ClipboardList, Factory, CreditCard,\n  Search, ClipboardCheck, X, Target, Code2, ShoppingBag,\n} from 'lucide-react'\nimport { useQuery } from '@tanstack/react-query'\nimport { cn } from '@/lib/utils'\nimport type { Config } from '@/components/layout/ClientShell'\n\ninterface Props {\n  tenantSlug: string; tenantName: string; config: Config\n  open: boolean; onClose: () => void\n}\n\nexport default function Sidebar({ tenantSlug, tenantName, config, open, onClose }: Props) {\n  const pathname = usePathname()\n  const base     = `/${tenantSlug}`\n\n  const { data: meuAcessoRaw } = useQuery({\n    queryKey: ['meu-acesso', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/perfis/meu-acesso`)).json(),\n    staleTime: 60000,\n  })\n  const nomeUsuario = meuAcessoRaw?.data?.nome ?? tenantName\n  const initials    = nomeUsuario.split(' ').slice(0, 2).map((w: string) => w[0]).join('').toUpperCase()\n  const isAdmin     = meuAcessoRaw?.data?.isAdmin ?? true\n  const modulos     = meuAcessoRaw?.data?.modulos ?? {}\n  // Helper: tem acesso ao m\u00f3dulo? Admin tem acesso a tudo\n  function temAcesso(modulo: string) { return isAdmin || modulos[modulo] === true }\n\n  const fixos = [\n    ...(temAcesso('dashboard') ? [{ label: 'Dashboard', href: '', icon: BarChart3 }] : []),\n    {\n      label: 'Cadastros', icon: Users,\n      children: [\n        { label: 'Clientes',          href: '/cadastros/clientes' },\n        { label: 'Fornecedores',      href: '/cadastros/fornecedores' },\n        { label: 'Produtos',          href: '/cadastros/produtos' },\n        { label: 'Insumos',           href: '/cadastros/insumos' },\n        { label: 'Fichas T\u00e9cnicas',   href: '/cadastros/ficha-tecnica' },\n        { label: 'Formas Pagamento',  href: '/cadastros/formas-pagamento' },\n        { label: 'Usu\u00e1rios',          href: '/cadastros/usuarios' },\n        { label: 'Perfis de Acesso',  href: '/perfis' },\n        { label: 'Dom\u00ednios',          href: '/cadastros/dominios' },\n      ],\n    },\n  ]\n\n  const estoqueLigado =\n    config.estoqueAtivo || config.entradaNfeAtivo || config.perdaProdutoAtivo || config.contagemInventarioAtivo || config.multiplosLocaisAtivo\n\n  const modulares = [\n    ...(config.metasAtivo     && temAcesso('metas')      ? [{ label: 'Metas & Simulador', href: '/metas',      icon: Target }]        : []),\n    ...(config.consultasAtivo && temAcesso('consultas')  ? [{ label: 'Consultas',         href: '/consultas',  icon: Search }]         : []),\n    ...(config.pedidosAtivo   && temAcesso('pedidos')    ? [{ label: 'Pedidos',           href: '/pedidos',    icon: ClipboardList }]  : []),\n    ...(config.comprasAtivo                              ? [{\n      label: 'Compras', icon: ShoppingBag,\n      children: [\n        { label: 'Compra R\u00e1pida',    href: '/compras/rapida' },\n        { label: 'Compras Avan\u00e7ado', href: '/compras' },\n      ],\n    }] : []),\n    ...(config.planoAcaoAtivo && temAcesso('planoAcao')  ? [{ label: 'Plano de A\u00e7\u00e3o',     href: '/plano-acao', icon: ClipboardCheck }] : []),\n    ...(config.producaoAtivo  && temAcesso('producao')   ? [{ label: 'Produ\u00e7\u00e3o',          href: '/producao',   icon: Factory }]        : []),\n    ...(estoqueLigado         && temAcesso('estoque')    ? [{ label: 'Estoque',           href: '/estoque',    icon: Boxes }]          : []),\n    ...(config.comandasAtivo  && temAcesso('comandas')   ? [{ label: 'Comandas',          href: '/comandas',   icon: CreditCard }]     : []),\n    ...(config.fiscalAtivo    && temAcesso('fiscal')     ? [{ label: 'Fiscal',            href: '/fiscal',     icon: CreditCard }]     : []),\n  ]\n\n  const finais = [\n    ...(temAcesso('vendas')     ? [{ label: 'Vendas',     href: '/vendas',     icon: ShoppingCart }] : []),\n    ...(temAcesso('financeiro') ? [{ label: 'Financeiro', href: '/financeiro', icon: DollarSign }]   : []),\n  ]\n\n  const allItems = [...fixos, ...modulares, ...finais]\n\n  function isActive(href: string) {\n    const path = href.split('?')[0] // ignora query string na compara\u00e7\u00e3o\n    const full = `${base}${path}`\n    return path === '' ? pathname === base : pathname.startsWith(full)\n  }\n\n  return (\n    <aside\n      className={cn(\n        'fixed lg:static inset-y-0 left-0 z-40 w-60 h-screen flex flex-col flex-shrink-0',\n        'transition-transform duration-300 ease-in-out',\n        open ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'\n      )}\n      style={{ backgroundColor: '#0F1117' }}>\n\n      <div className=\"flex items-center justify-between px-5 pt-5 pb-4 border-b border-white/5\">\n        <Link href={base} onClick={onClose} className=\"flex items-center gap-2 hover:opacity-80 transition-opacity\">\n          <Code2 size={18} style={{ color: '#2ecc71' }} />\n          <div className=\"flex items-baseline\">\n            <span className=\"text-[19px] font-bold text-white tracking-tight\">sistematiza</span>\n            <span className=\"text-[19px] font-bold tracking-tight\" style={{ color: '#2ecc71' }}>.ai</span>\n          </div>\n        </Link>\n        <button onClick={onClose} className=\"lg:hidden text-white/30 hover:text-white/70 p-1 rounded\">\n          <X size={16} />\n        </button>\n      </div>\n\n      <nav className=\"flex-1 px-2 py-3 overflow-y-auto space-y-0.5\">\n        {allItems.map(item => {\n          if ('children' in item && item.children) {\n            const anyActive = item.children.some(c => isActive(c.href))\n            return (\n              <div key={item.label} className=\"group/menu relative\">\n                <button\n                  className={cn('w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm transition-colors',\n                    anyActive ? 'text-white' : 'text-white/50 group-hover/menu:text-white/80')}>\n                  <span className=\"flex items-center gap-3\"><item.icon size={15} />{item.label}</span>\n                  <ChevronRight size={12} className=\"transition-transform duration-200 group-hover/menu:rotate-90\" />\n                </button>\n                <div className=\"ml-7 mt-0.5 space-y-0.5 max-h-0 overflow-hidden group-hover/menu:max-h-96 transition-[max-height] duration-200 ease-in-out\">\n                  {item.children.map((child: any) => {\n                    const active = isActive(child.href)\n                    return (\n                      <Link key={child.href} href={`${base}${child.href}`} onClick={onClose}\n                        className={cn('block px-3 py-1.5 rounded-md text-sm transition-all',\n                          active\n                            ? 'text-white font-medium bg-[#2ecc71]/10 border-l-2 border-[#2ecc71] pl-[10px]'\n                            : 'text-white/40 hover:text-white/70 hover:bg-white/5')}>\n                        {child.label}\n                      </Link>\n                    )\n                  })}\n                </div>\n              </div>\n            )\n          }\n          const active = isActive((item as any).href ?? '')\n          return (\n            <Link key={item.label} href={`${base}${(item as any).href ?? ''}`} onClick={onClose}\n              className={cn('flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-all',\n                active\n                  ? 'text-white font-medium bg-[#2ecc71]/10 border-l-2 border-[#2ecc71] pl-[10px]'\n                  : 'text-white/50 hover:text-white/80 hover:bg-white/5')}>\n              <item.icon size={15} />\n              {item.label}\n            </Link>\n          )\n        })}\n      </nav>\n\n      <div className=\"border-t border-white/5 p-4\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 text-[11px] font-bold\"\n            style={{ backgroundColor: 'rgba(46,204,113,0.15)', color: '#2ecc71', border: '1px solid rgba(46,204,113,0.25)' }}>\n            {initials}\n          </div>\n          <div className=\"min-w-0\">\n            <p className=\"text-xs font-semibold text-white/80 truncate\">{nomeUsuario}</p>\n            <p className=\"text-[10px] text-white/30 truncate\">{tenantName}</p>\n          </div>\n        </div>\n      </div>\n    </aside>\n  )\n}\n"],
  ["components/modules/dashboard/DashboardHome.tsx", "'use client'\nimport { useQuery } from '@tanstack/react-query'\nimport {\n  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,\n  LineChart, Line, PieChart, Pie, Cell, Legend,\n} from 'recharts'\n\ninterface Props { tenantSlug: string }\n\nfunction fmt(v: number) { return `R$ ${v.toLocaleString('pt-BR', { minimumFractionDigits: 0 })}` }\nconst COLORS = ['#2ecc71','#3498db','#e74c3c','#f39c12','#9b59b6','#1abc9c','#e67e22','#95a5a6']\nconst tooltipFmt = (v: unknown) => fmt(Number(v ?? 0))\n\nexport default function DashboardHome({ tenantSlug }: Props) {\n  const { data, isLoading } = useQuery({\n    queryKey: ['dashboard', tenantSlug],\n    queryFn:  async () => {\n      const res = await fetch(`/api/${tenantSlug}/dashboard`)\n      if (!res.ok) return null\n      return res.json()\n    },\n    refetchInterval: 60000,\n    retry: false,\n  })\n\n  if (isLoading) return (\n    <div className=\"flex items-center justify-center h-64\">\n      <p className=\"text-sm text-gray-400\">Carregando dashboard...</p>\n    </div>\n  )\n\n  if (!data?.data) return (\n    <div>\n      <div className=\"mb-6\">\n        <h1 className=\"text-2xl font-semibold text-gray-900\">Dashboard</h1>\n        <p className=\"text-sm text-gray-400 mt-0.5\">Vis\u00e3o geral do neg\u00f3cio</p>\n      </div>\n      <div className=\"bg-amber-50 border border-amber-200 rounded-xl p-6 text-center\">\n        <p className=\"text-sm text-amber-700\">Dashboard dispon\u00edvel ap\u00f3s registrar as primeiras vendas.</p>\n      </div>\n    </div>\n  )\n\n  const raw = data.data\n\n  const faturamento6m     = Array.isArray(raw.faturamento6m)     ? raw.faturamento6m     : []\n  const vendasDia         = Array.isArray(raw.vendasDia)         ? raw.vendasDia         : []\n  const topProdutos       = Array.isArray(raw.topProdutos)       ? raw.topProdutos       : []\n  const receitaVsDespesas = Array.isArray(raw.receitaVsDespesas) ? raw.receitaVsDespesas : []\n  const estoqueCritico    = Array.isArray(raw.estoqueCritico)    ? raw.estoqueCritico    : []\n  const porForma          = Array.isArray(raw.porForma)          ? raw.porForma          : []\n\n  // Usa campos diretos da API \u2014 mais confi\u00e1vel que derivar do array\n  const totalHoje = raw.receitaHoje ?? vendasDia[vendasDia.length - 1]?.valor ?? 0\n  const totalMes  = raw.receitaMes  ?? faturamento6m[faturamento6m.length - 1]?.valor ?? 0\n  const qtdMes    = raw.qtdMes ?? 0\n\n  return (\n    <div className=\"space-y-6\">\n      <div>\n        <h1 className=\"text-2xl font-semibold text-gray-900\">Dashboard</h1>\n        <p className=\"text-sm text-gray-400 mt-0.5\">Vis\u00e3o geral do neg\u00f3cio</p>\n      </div>\n\n      {/* KPIs */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3\">\n        {[\n          { label: 'Hoje',               value: fmt(totalHoje),  sub: '', color: '#2ecc71' },\n          { label: 'Faturamento do m\u00eas', value: fmt(totalMes),   sub: `${qtdMes} venda${qtdMes !== 1 ? 's' : ''}` },\n          { label: 'Estoque cr\u00edtico',    value: String(estoqueCritico.length), sub: 'produtos abaixo do m\u00ednimo', color: estoqueCritico.length > 0 ? '#e74c3c' : undefined },\n          { label: 'Top produto',        value: topProdutos[0]?.nome?.split(' ').slice(0, 2).join(' ') ?? '\u2014', sub: topProdutos[0] ? `${topProdutos[0].qtd} un` : '' },\n        ].map((kpi, i) => (\n          <div key={i} className=\"bg-white rounded-xl border border-gray-100 p-4\">\n            <p className=\"text-xs text-gray-400\">{kpi.label}</p>\n            <p className=\"text-xl font-bold mt-1 truncate\" style={{ color: kpi.color ?? '#0F1117' }}>{kpi.value}</p>\n            {kpi.sub && <p className=\"text-xs text-gray-400 mt-0.5\">{kpi.sub}</p>}\n          </div>\n        ))}\n      </div>\n\n      {/* Linha 1 */}\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Faturamento \u2014 \u00faltimos 6 meses</h3>\n          {faturamento6m.length === 0 ? (\n            <p className=\"text-sm text-gray-400 text-center py-12\">Sem dados</p>\n          ) : (\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <BarChart data={faturamento6m} margin={{ left: -20 }}>\n                <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n                <XAxis dataKey=\"mes\" tick={{ fontSize: 11, fill: '#9ca3af' }} />\n                <YAxis tick={{ fontSize: 11, fill: '#9ca3af' }} tickFormatter={v => `R$${(Number(v) / 1000).toFixed(0)}k`} />\n                <Tooltip formatter={tooltipFmt} labelStyle={{ fontSize: 12 }} />\n                <Bar dataKey=\"valor\" fill=\"#2ecc71\" radius={[4, 4, 0, 0]} name=\"Faturamento\" />\n              </BarChart>\n            </ResponsiveContainer>\n          )}\n        </div>\n\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Vendas por dia \u2014 m\u00eas atual</h3>\n          {vendasDia.length === 0 ? (\n            <p className=\"text-sm text-gray-400 text-center py-12\">Sem dados</p>\n          ) : (\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <LineChart data={vendasDia} margin={{ left: -20 }}>\n                <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n                <XAxis dataKey=\"dia\" tick={{ fontSize: 11, fill: '#9ca3af' }} />\n                <YAxis tick={{ fontSize: 11, fill: '#9ca3af' }} tickFormatter={v => `R$${(Number(v) / 1000).toFixed(0)}k`} />\n                <Tooltip formatter={tooltipFmt} />\n                <Line type=\"monotone\" dataKey=\"valor\" stroke=\"#2ecc71\" strokeWidth={2} dot={false} name=\"Vendas\" />\n              </LineChart>\n            </ResponsiveContainer>\n          )}\n        </div>\n      </div>\n\n      {/* Linha 2 */}\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Top 5 produtos \u2014 este m\u00eas</h3>\n          {topProdutos.length === 0 ? (\n            <p className=\"text-sm text-gray-400 text-center py-12\">Sem vendas registradas</p>\n          ) : (\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <BarChart data={topProdutos} layout=\"vertical\" margin={{ left: 10, right: 20 }}>\n                <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n                <XAxis type=\"number\" tick={{ fontSize: 11, fill: '#9ca3af' }} />\n                <YAxis type=\"category\" dataKey=\"nome\" tick={{ fontSize: 10, fill: '#6b7280' }} width={100}\n                  tickFormatter={(v: string) => v.length > 14 ? v.slice(0, 14) + '\u2026' : v} />\n                <Tooltip formatter={(v: unknown, name: unknown) => [\n                  name === 'qtd' ? `${v} un` : fmt(Number(v ?? 0)),\n                  name === 'qtd' ? 'Quantidade' : 'Valor',\n                ]} />\n                <Bar dataKey=\"qtd\" fill=\"#3498db\" radius={[0, 4, 4, 0]} name=\"qtd\" />\n              </BarChart>\n            </ResponsiveContainer>\n          )}\n        </div>\n\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Receita vs Despesas \u2014 6 meses</h3>\n          {receitaVsDespesas.length === 0 ? (\n            <p className=\"text-sm text-gray-400 text-center py-12\">Sem dados</p>\n          ) : (\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <BarChart data={receitaVsDespesas} margin={{ left: -20 }}>\n                <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n                <XAxis dataKey=\"mes\" tick={{ fontSize: 11, fill: '#9ca3af' }} />\n                <YAxis tick={{ fontSize: 11, fill: '#9ca3af' }} tickFormatter={v => `R$${(Number(v) / 1000).toFixed(0)}k`} />\n                <Tooltip formatter={tooltipFmt} />\n                <Legend iconSize={10} wrapperStyle={{ fontSize: 11 }} />\n                <Bar dataKey=\"receita\"  fill=\"#2ecc71\" radius={[4, 4, 0, 0]} name=\"Receita\" />\n                <Bar dataKey=\"despesas\" fill=\"#e74c3c\" radius={[4, 4, 0, 0]} name=\"Despesas\" />\n              </BarChart>\n            </ResponsiveContainer>\n          )}\n        </div>\n      </div>\n\n      {/* Linha 3 */}\n      <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Formas de pagamento \u2014 m\u00eas atual</h3>\n          {porForma.length === 0 ? (\n            <p className=\"text-sm text-gray-400 text-center py-12\">Sem dados</p>\n          ) : (\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <PieChart>\n                <Pie data={porForma} dataKey=\"valor\" nameKey=\"forma\" cx=\"50%\" cy=\"50%\" outerRadius={75}\n                  label={({ forma, percent }: any) => `${forma} ${(percent * 100).toFixed(0)}%`}\n                  labelLine={false}>\n                  {porForma.map((_: any, i: number) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}\n                </Pie>\n                <Tooltip formatter={tooltipFmt} />\n              </PieChart>\n            </ResponsiveContainer>\n          )}\n        </div>\n\n        <div className=\"bg-white rounded-xl border border-gray-100 p-5\">\n          <h3 className=\"text-sm font-semibold text-gray-700 mb-4\">Estoque cr\u00edtico</h3>\n          {estoqueCritico.length === 0 ? (\n            <div className=\"flex items-center justify-center h-40\">\n              <div className=\"text-center\">\n                <p className=\"text-3xl mb-2\">\u2713</p>\n                <p className=\"text-sm text-green-600 font-medium\">Estoque OK</p>\n                <p className=\"text-xs text-gray-400 mt-1\">Todos os itens acima do m\u00ednimo</p>\n              </div>\n            </div>\n          ) : (\n            <div className=\"space-y-2 max-h-48 overflow-y-auto\">\n              {estoqueCritico.map((p: any, i: number) => (\n                <div key={i} className=\"flex items-center justify-between py-2 border-b border-gray-50 last:border-0\">\n                  <div className=\"min-w-0 flex-1\">\n                    <p className=\"text-sm text-gray-900 truncate\">{p.nome}</p>\n                    <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded-full ${p.tipo === 'insumo' ? 'bg-blue-50 text-blue-600' : 'bg-purple-50 text-purple-600'}`}>\n                      {p.tipo === 'insumo' ? 'Insumo' : 'Produto'}\n                    </span>\n                  </div>\n                  <div className=\"flex items-center gap-3 flex-shrink-0 ml-2\">\n                    <div className=\"w-20 bg-gray-100 rounded-full h-1.5\">\n                      <div className=\"bg-red-500 h-1.5 rounded-full\"\n                        style={{ width: `${Math.min(100, (p.estoqueAtual / Math.max(1, p.estoqueMinimo)) * 100)}%` }} />\n                    </div>\n                    <span className=\"text-xs font-medium text-red-600 w-16 text-right\">{Number(p.estoqueAtual).toFixed(1)}/{Number(p.estoqueMinimo).toFixed(1)}</span>\n                  </div>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n      </div>\n    </div>\n  )\n}\n"],
  ["app/api/[tenant]/dashboard/route.ts", "// @ts-nocheck\nimport type { NextRequest } from 'next/server'\nimport { resolveTenant } from '@/lib/auth/tenant'\nimport { pool } from '@/lib/db/connection'\nimport { ok, serverError } from '@/lib/api/responses'\n\ntype Params = { params: { tenant: string } }\n\nexport async function GET(req: NextRequest, { params }: Params) {\n  try {\n    const tenant = await resolveTenant(params.tenant)\n    const client = await pool.connect()\n    try {\n      await client.query(`SET search_path TO \"${tenant.schemaName}\", public`)\n\n      const [fat6m, vendasDia, topProd, receita6m, despesas6m, estCritico, porForma, kpisHoje] = await Promise.all([\n        client.query(`\n          SELECT TO_CHAR(DATE_TRUNC('month', vendida_em), 'Mon/YY') as mes,\n                 COALESCE(SUM(total),0)::bigint as valor, COUNT(*)::int as qtd\n          FROM t_venda WHERE active_flg=true AND vendida_em >= NOW()-INTERVAL '6 months'\n          GROUP BY DATE_TRUNC('month', vendida_em) ORDER BY DATE_TRUNC('month', vendida_em)\n        `),\n        client.query(`\n          SELECT EXTRACT(DAY FROM vendida_em AT TIME ZONE 'America/Sao_Paulo')::int as dia,\n                 COALESCE(SUM(total),0)::bigint as valor\n          FROM t_venda WHERE active_flg=true\n            AND DATE_TRUNC('month', vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                = DATE_TRUNC('month', NOW() AT TIME ZONE 'America/Sao_Paulo')\n          GROUP BY EXTRACT(DAY FROM vendida_em AT TIME ZONE 'America/Sao_Paulo')\n          ORDER BY dia\n        `),\n        client.query(`\n          SELECT vi.nome_produto, COALESCE(SUM(vi.quantidade),0)::int as qtd,\n                 COALESCE(SUM(vi.subtotal),0)::bigint as valor\n          FROM t_venda_item vi JOIN t_venda v ON vi.venda_id=v.venda_id\n          WHERE v.active_flg=true\n            AND DATE_TRUNC('month', v.vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                = DATE_TRUNC('month', NOW() AT TIME ZONE 'America/Sao_Paulo')\n          GROUP BY vi.nome_produto ORDER BY qtd DESC LIMIT 5\n        `),\n        client.query(`\n          SELECT TO_CHAR(DATE_TRUNC('month', vendida_em), 'Mon/YY') as mes,\n                 COALESCE(SUM(total),0)::bigint as valor\n          FROM t_venda WHERE active_flg=true AND vendida_em >= NOW()-INTERVAL '6 months'\n          GROUP BY DATE_TRUNC('month', vendida_em) ORDER BY DATE_TRUNC('month', vendida_em)\n        `),\n        client.query(`\n          SELECT TO_CHAR(DATE_TRUNC('month', data_despesa), 'Mon/YY') as mes,\n                 COALESCE(SUM(valor),0)::bigint as valor\n          FROM t_despesa WHERE active_flg=true AND data_despesa >= NOW()-INTERVAL '6 months'\n          GROUP BY DATE_TRUNC('month', data_despesa) ORDER BY DATE_TRUNC('month', data_despesa)\n        `).catch(() => ({ rows: [] })),\n        client.query(`\n          SELECT nome, estoque_atual::float as estoque_atual, estoque_minimo::float as estoque_minimo, 'produto' as tipo\n          FROM t_produto\n          WHERE active_flg=true AND estoque_minimo > 0 AND estoque_atual <= estoque_minimo\n          UNION ALL\n          SELECT nome, estoque_atual::float, estoque_minimo::float, 'insumo' as tipo\n          FROM t_insumo\n          WHERE active_flg=true AND estoque_minimo > 0 AND estoque_atual <= estoque_minimo\n          ORDER BY estoque_atual LIMIT 12\n        `),\n        client.query(`\n          SELECT vp.forma, COALESCE(SUM(vp.valor),0)::bigint as total\n          FROM t_venda_pagamento vp JOIN t_venda v ON vp.venda_id=v.venda_id\n          WHERE v.active_flg=true\n            AND DATE_TRUNC('month', v.vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                = DATE_TRUNC('month', NOW() AT TIME ZONE 'America/Sao_Paulo')\n          GROUP BY vp.forma ORDER BY total DESC\n        `),\n        client.query(`\n          SELECT\n            COALESCE(SUM(CASE WHEN DATE_TRUNC('day', vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                              = DATE_TRUNC('day', NOW() AT TIME ZONE 'America/Sao_Paulo')\n                         THEN total ELSE 0 END), 0)::bigint as receita_hoje,\n            COALESCE(SUM(CASE WHEN DATE_TRUNC('month', vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                              = DATE_TRUNC('month', NOW() AT TIME ZONE 'America/Sao_Paulo')\n                         THEN total ELSE 0 END), 0)::bigint as receita_mes,\n            COUNT(CASE WHEN DATE_TRUNC('month', vendida_em AT TIME ZONE 'America/Sao_Paulo')\n                            = DATE_TRUNC('month', NOW() AT TIME ZONE 'America/Sao_Paulo')\n                  THEN 1 END)::int as qtd_mes\n          FROM t_venda WHERE active_flg=true\n        `),\n      ])\n\n      const mesesSet = new Set([...receita6m.rows.map(r => r.mes), ...despesas6m.rows.map(r => r.mes)])\n      const receitaVsDespesas = Array.from(mesesSet).map(mes => ({\n        mes,\n        receita:  Number(receita6m.rows.find(r => r.mes === mes)?.valor ?? 0) / 100,\n        despesas: Number(despesas6m.rows.find(r => r.mes === mes)?.valor ?? 0) / 100,\n      }))\n\n      const kpi = kpisHoje.rows[0] ?? {}\n\n      return ok({\n        receitaHoje:       Number(kpi.receita_hoje ?? 0) / 100,\n        receitaMes:        Number(kpi.receita_mes ?? 0) / 100,\n        qtdMes:            Number(kpi.qtd_mes ?? 0),\n        faturamento6m:     fat6m.rows.map(r => ({ mes: r.mes, valor: Number(r.valor)/100, qtd: Number(r.qtd) })),\n        vendasDia:         vendasDia.rows.map(r => ({ dia: String(r.dia), valor: Number(r.valor)/100 })),\n        topProdutos:       topProd.rows.map(r => ({ nome: r.nome_produto, qtd: Number(r.qtd), valor: Number(r.valor)/100 })),\n        receitaVsDespesas,\n        estoqueCritico:    estCritico.rows.map(r => ({ nome: r.nome, estoqueAtual: Number(r.estoque_atual), estoqueMinimo: Number(r.estoque_minimo) })),\n        porForma:          porForma.rows.map(r => ({ forma: r.forma, valor: Number(r.total)/100 })),\n      })\n    } finally {\n      client.release()\n    }\n  } catch (err) {\n    return serverError(err)\n  }\n}\n"],
  ["components/modules/perfis/PerfisView.tsx", "'use client'\nimport { useState } from 'react'\nimport { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'\nimport { Plus, X, Trash2, Pencil, Shield, Check, ChevronDown, ChevronUp } from 'lucide-react'\nimport { Button }       from '@/components/ui/button'\nimport { Input }        from '@/components/ui/input'\nimport { Label }        from '@/components/ui/label'\nimport { useToast }     from '@/components/ui/Toast'\nimport { ConfirmModal } from '@/components/ui/ConfirmModal'\n\ninterface Props { tenantSlug: string }\n\nconst MODULOS_CONFIG = [\n  {\n    grupo: 'Acesso',\n    itens: [\n      { key: 'isAdmin',          label: 'Administrador (acesso total)',  bold: true },\n      { key: 'acessoGerencial',  label: 'Acesso Gerencial' },\n      { key: 'acessoPdv',        label: 'Acesso PDV' },\n      { key: 'acessoComanda',    label: 'Acesso Comandas' },\n      { key: 'acessoDelivery',   label: 'Acesso Delivery' },\n    ],\n  },\n  {\n    grupo: 'M\u00f3dulos vis\u00edveis na sidebar',\n    itens: [\n      { key: 'moduloDashboard',  label: 'Dashboard' },\n      { key: 'moduloCadastros',  label: 'Cadastros' },\n      { key: 'moduloVendas',     label: 'Vendas' },\n      { key: 'moduloFinanceiro', label: 'Financeiro' },\n      { key: 'moduloEstoque',    label: 'Estoque' },\n      { key: 'moduloProducao',   label: 'Produ\u00e7\u00e3o' },\n      { key: 'moduloPedidos',    label: 'Pedidos' },\n      { key: 'moduloComandas',   label: 'Comandas' },\n      { key: 'moduloConsultas',  label: 'Consultas' },\n      { key: 'moduloFiscal',     label: 'Fiscal' },\n      { key: 'moduloPlanoAcao',  label: 'Plano de A\u00e7\u00e3o' },\n      { key: 'moduloMetas',      label: 'Metas & Simulador' },\n      { key: 'moduloUsuarios',   label: 'Usu\u00e1rios & Perfis' },\n    ],\n  },\n]\n\nconst DEFAULT_FORM = {\n  nome: '', descricao: '',\n  isAdmin: false,\n  acessoGerencial: false, acessoPdv: true, acessoComanda: false, acessoDelivery: false,\n  moduloDashboard: true,  moduloCadastros: true, moduloVendas: true,\n  moduloFinanceiro: false, moduloEstoque: false, moduloProducao: false,\n  moduloPedidos: false,   moduloComandas: false, moduloConsultas: false,\n  moduloFiscal: false,    moduloPlanoAcao: false, moduloMetas: false, moduloUsuarios: false,\n  percDescontoMax: 0, valorDescontoMax: 0,\n}\n\nexport default function PerfisView({ tenantSlug }: Props) {\n  const qc        = useQueryClient()\n  const { toast } = useToast()\n  const api       = `/api/${tenantSlug}/perfis`\n\n  const [showModal, setShowModal]   = useState(false)\n  const [editando, setEditando]     = useState<any>(null)\n  const [confirmDel, setConfirmDel] = useState<any>(null)\n  const [form, setForm]             = useState({ ...DEFAULT_FORM })\n  const setF = (k: string, v: any) => setForm(p => ({ ...p, [k]: v }))\n\n  const { data: perfisRaw, isLoading } = useQuery({\n    queryKey: ['perfis', tenantSlug],\n    queryFn:  async () => (await fetch(api)).json(),\n  })\n\n  const salvarMut = useMutation({\n    mutationFn: async () => {\n      const url    = editando ? `${api}/${editando.perfilId}` : api\n      const method = editando ? 'PUT' : 'POST'\n      const res = await fetch(url, {\n        method, headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          ...form,\n          percDescontoMax:  Number(form.percDescontoMax),\n          valorDescontoMax: Math.round(Number(form.valorDescontoMax) * 100),\n        }),\n      })\n      const d = await res.json()\n      if (!res.ok) throw new Error(d.message ?? 'Erro ao salvar')\n      return d\n    },\n    onSuccess: () => {\n      qc.invalidateQueries({ queryKey: ['perfis', tenantSlug] })\n      setShowModal(false)\n      setEditando(null)\n      toast(editando ? 'Perfil atualizado!' : 'Perfil criado!')\n    },\n    onError: (e: any) => toast(e.message || 'Erro ao salvar.', 'error'),\n  })\n\n  const excluirMut = useMutation({\n    mutationFn: async (id: number) => {\n      const res = await fetch(`${api}/${id}`, { method: 'DELETE' })\n      const d   = await res.json()\n      if (!res.ok) throw new Error(d.message ?? 'Erro ao excluir')\n      return d\n    },\n    onSuccess: () => { qc.invalidateQueries({ queryKey: ['perfis', tenantSlug] }); toast('Perfil exclu\u00eddo.') },\n    onError:   (e: any) => toast(e.message || 'Erro ao excluir.', 'error'),\n  })\n\n  function abrirNovo() {\n    setEditando(null)\n    setForm({ ...DEFAULT_FORM })\n    setShowModal(true)\n  }\n\n  function abrirEditar(p: any) {\n    setEditando(p)\n    setForm({\n      nome:             p.nome ?? '',\n      descricao:        p.descricao ?? '',\n      isAdmin:          p.isAdmin ?? false,\n      acessoGerencial:  p.acessoGerencial ?? false,\n      acessoPdv:        p.acessoPdv ?? true,\n      acessoComanda:    p.acessoComanda ?? false,\n      acessoDelivery:   p.acessoDelivery ?? false,\n      moduloDashboard:  p.moduloDashboard ?? true,\n      moduloCadastros:  p.moduloCadastros ?? true,\n      moduloVendas:     p.moduloVendas ?? true,\n      moduloFinanceiro: p.moduloFinanceiro ?? false,\n      moduloEstoque:    p.moduloEstoque ?? false,\n      moduloProducao:   p.moduloProducao ?? false,\n      moduloPedidos:    p.moduloPedidos ?? false,\n      moduloComandas:   p.moduloComandas ?? false,\n      moduloConsultas:  p.moduloConsultas ?? false,\n      moduloFiscal:     p.moduloFiscal ?? false,\n      moduloPlanoAcao:  p.moduloPlanoAcao ?? false,\n      moduloMetas:      p.moduloMetas ?? false,\n      moduloUsuarios:   p.moduloUsuarios ?? false,\n      percDescontoMax:  Number(p.percDescontoMax ?? 0),\n      valorDescontoMax: Number(p.valorDescontoMax ?? 0) / 100,\n    })\n    setShowModal(true)\n  }\n\n  const perfis = Array.isArray(perfisRaw?.data) ? perfisRaw.data : []\n\n  function TagModulo({ ativo, label }: { ativo: boolean; label: string }) {\n    if (!ativo) return null\n    return (\n      <span className=\"text-[10px] bg-green-50 text-green-700 border border-green-200 rounded-full px-1.5 py-0.5 whitespace-nowrap\">\n        {label}\n      </span>\n    )\n  }\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div>\n          <h1 className=\"text-2xl font-semibold text-gray-900\">Perfis de Acesso</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">Defina quais m\u00f3dulos cada perfil pode acessar</p>\n        </div>\n        <Button onClick={abrirNovo}>\n          <Plus size={15} className=\"mr-1.5\" /> Novo perfil\n        </Button>\n      </div>\n\n      {isLoading ? (\n        <div className=\"text-center py-12 text-sm text-gray-400\">Carregando...</div>\n      ) : perfis.length === 0 ? (\n        <div className=\"bg-white rounded-xl border border-gray-100 p-12 text-center\">\n          <Shield size={28} className=\"text-gray-200 mx-auto mb-2\" />\n          <p className=\"text-sm text-gray-400\">Nenhum perfil cadastrado.</p>\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          {perfis.map((p: any) => (\n            <div key={p.perfilId} className=\"bg-white rounded-xl border border-gray-100 p-5\">\n              <div className=\"flex items-start justify-between gap-3\">\n                <div className=\"flex-1 min-w-0\">\n                  <div className=\"flex items-center gap-2 mb-1\">\n                    <h3 className=\"text-base font-semibold text-gray-900\">{p.nome}</h3>\n                    {p.isAdmin && (\n                      <span className=\"text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full font-medium\">Admin</span>\n                    )}\n                  </div>\n                  {p.descricao && <p className=\"text-sm text-gray-400 mb-3\">{p.descricao}</p>}\n\n                  {/* M\u00f3dulos vis\u00edveis */}\n                  <div className=\"flex flex-wrap gap-1.5 mt-2\">\n                    <TagModulo ativo={p.acessoGerencial}  label=\"Gerencial\" />\n                    <TagModulo ativo={p.acessoPdv}        label=\"PDV\" />\n                    <TagModulo ativo={p.acessoComanda}    label=\"Comanda\" />\n                    <TagModulo ativo={p.acessoDelivery}   label=\"Delivery\" />\n                    <TagModulo ativo={p.moduloDashboard}  label=\"Dashboard\" />\n                    <TagModulo ativo={p.moduloCadastros}  label=\"Cadastros\" />\n                    <TagModulo ativo={p.moduloVendas}     label=\"Vendas\" />\n                    <TagModulo ativo={p.moduloFinanceiro} label=\"Financeiro\" />\n                    <TagModulo ativo={p.moduloEstoque}    label=\"Estoque\" />\n                    <TagModulo ativo={p.moduloProducao}   label=\"Produ\u00e7\u00e3o\" />\n                    <TagModulo ativo={p.moduloPedidos}    label=\"Pedidos\" />\n                    <TagModulo ativo={p.moduloComandas}   label=\"Comandas\" />\n                    <TagModulo ativo={p.moduloFiscal}     label=\"Fiscal\" />\n                    <TagModulo ativo={p.moduloMetas}      label=\"Metas\" />\n                    <TagModulo ativo={p.moduloUsuarios}   label=\"Usu\u00e1rios\" />\n                  </div>\n                </div>\n\n                <div className=\"flex gap-2 flex-shrink-0\">\n                  <Button size=\"sm\" variant=\"outline\" onClick={() => abrirEditar(p)}>\n                    <Pencil size={13} className=\"mr-1\" /> Editar\n                  </Button>\n                  <button\n                    onClick={() => setConfirmDel(p)}\n                    className=\"p-2 text-gray-300 hover:text-red-500 rounded-lg hover:bg-red-50 transition-colors\"\n                  >\n                    <Trash2 size={15} />\n                  </button>\n                </div>\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* Modal Criar/Editar */}\n      {showModal && (\n        <div className=\"fixed inset-0 z-50 flex items-center justify-center\" style={{ backgroundColor: 'rgba(0,0,0,0.4)' }}>\n          <div className=\"bg-white rounded-2xl shadow-xl w-full max-w-lg mx-4 max-h-[90vh] flex flex-col\">\n            <div className=\"flex items-center justify-between p-6 border-b border-gray-100 flex-shrink-0\">\n              <h2 className=\"text-lg font-semibold\">{editando ? `Editar: ${editando.nome}` : 'Novo perfil'}</h2>\n              <button onClick={() => { setShowModal(false); setEditando(null) }} className=\"text-gray-400 hover:text-gray-600\">\n                <X size={18} />\n              </button>\n            </div>\n\n            <div className=\"flex-1 overflow-y-auto p-6 space-y-5\">\n              {/* Nome e descri\u00e7\u00e3o */}\n              <div>\n                <Label>Nome do perfil *</Label>\n                <Input value={form.nome} onChange={e => setF('nome', e.target.value)} className=\"mt-1\" placeholder=\"Ex: Vendedor, Caixa, Supervisor\" autoFocus />\n              </div>\n              <div>\n                <Label>Descri\u00e7\u00e3o</Label>\n                <Input value={form.descricao} onChange={e => setF('descricao', e.target.value)} className=\"mt-1\" placeholder=\"Opcional\" />\n              </div>\n\n              {/* Permiss\u00f5es por grupo */}\n              {MODULOS_CONFIG.map(grupo => (\n                <div key={grupo.grupo}>\n                  <p className=\"text-xs font-bold text-gray-500 uppercase tracking-wide mb-2\">{grupo.grupo}</p>\n                  <div className=\"space-y-2 pl-1\">\n                    {grupo.itens.map(item => (\n                      <label key={item.key} className=\"flex items-center gap-3 cursor-pointer group\">\n                        <div\n                          onClick={() => setF(item.key, !(form as any)[item.key])}\n                          className={`w-5 h-5 rounded flex items-center justify-center flex-shrink-0 border-2 transition-colors cursor-pointer ${\n                            (form as any)[item.key]\n                              ? 'bg-green-500 border-green-500'\n                              : 'border-gray-300 group-hover:border-green-400'\n                          }`}\n                        >\n                          {(form as any)[item.key] && <Check size={12} color=\"white\" strokeWidth={3} />}\n                        </div>\n                        <span className={`text-sm ${(item as any).bold ? 'font-semibold text-gray-900' : 'text-gray-700'}`}>\n                          {item.label}\n                        </span>\n                      </label>\n                    ))}\n                  </div>\n                </div>\n              ))}\n\n              {/* Desconto m\u00e1ximo */}\n              <div>\n                <p className=\"text-xs font-bold text-gray-500 uppercase tracking-wide mb-2\">Limites de Desconto</p>\n                <div className=\"grid grid-cols-2 gap-3\">\n                  <div>\n                    <Label>Desconto m\u00e1ximo (%)</Label>\n                    <Input type=\"number\" min=\"0\" max=\"100\" value={form.percDescontoMax}\n                      onChange={e => setF('percDescontoMax', Number(e.target.value))} className=\"mt-1\" placeholder=\"0\" />\n                  </div>\n                  <div>\n                    <Label>Valor m\u00e1ximo de desconto (R$)</Label>\n                    <Input type=\"number\" min=\"0\" step=\"0.01\" value={form.valorDescontoMax}\n                      onChange={e => setF('valorDescontoMax', Number(e.target.value))} className=\"mt-1\" placeholder=\"0,00\" />\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"flex justify-end gap-3 p-6 border-t border-gray-100 flex-shrink-0\">\n              <Button variant=\"outline\" onClick={() => { setShowModal(false); setEditando(null) }}>Cancelar</Button>\n              <Button onClick={() => salvarMut.mutate()} disabled={!form.nome || salvarMut.isPending}>\n                {salvarMut.isPending ? 'Salvando...' : editando ? 'Salvar altera\u00e7\u00f5es' : 'Criar perfil'}\n              </Button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {confirmDel && (\n        <ConfirmModal\n          title=\"Excluir perfil\"\n          message={`Excluir o perfil \"${confirmDel.nome}\"? Usu\u00e1rios vinculados a este perfil perder\u00e3o as configura\u00e7\u00f5es.`}\n          confirmLabel=\"Excluir\"\n          danger\n          onConfirm={() => { excluirMut.mutate(confirmDel.perfilId); setConfirmDel(null) }}\n          onCancel={() => setConfirmDel(null)}\n        />\n      )}\n    </div>\n  )\n}\n"],
  ["components/modules/vendas/VendasView.tsx", "'use client'\nimport { useState } from 'react'\nimport { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'\nimport { Plus, X, Trash2, Download, Eye } from 'lucide-react'\nimport { useRouter } from 'next/navigation'\nimport { Button } from '@/components/ui/button'\nimport { Input } from '@/components/ui/input'\nimport { Label } from '@/components/ui/label'\nimport { Badge } from '@/components/ui/badge'\nimport { TableSkeleton } from '@/components/ui/Skeleton'\nimport { ConfirmModal } from '@/components/ui/ConfirmModal'\nimport { useToast } from '@/components/ui/Toast'\nimport { useDominio } from '@/hooks/useDominio'\n\ninterface Props { tenantSlug: string }\n\nfunction fmt(c: number) { return (c / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) }\nfunction fmtDate(d: string) { return new Date(d).toLocaleDateString('pt-BR') }\nfunction fmtDateHora(d: string) {\n  return new Date(d).toLocaleString('pt-BR', {\n    day: '2-digit', month: '2-digit', year: 'numeric',\n    hour: '2-digit', minute: '2-digit',\n  })\n}\n\n// \u2500\u2500\u2500 Tipos \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ntype TipoPrecao = 'varejo' | 'atacado_a' | 'atacado_b' | 'atacado_c' | 'atacado_d' | 'atacado_e'\n\ninterface OpcaoPreco {\n  key:   TipoPrecao\n  label: string\n  valor: number // centavos\n}\n\ninterface ItemVenda {\n  _key:          string\n  produtoId:     number\n  nomeProduto:   string\n  quantidade:    number\n  tipoPrecao:    TipoPrecao\n  precoUnitario: number // centavos \u2014 calculado localmente para exibi\u00e7\u00e3o\n  subtotal:      number // centavos \u2014 calculado localmente para exibi\u00e7\u00e3o\n  _produto?:     any\n}\n\ninterface FormaPgto { forma: string; valor: string }\n\n// \u2500\u2500\u2500 Helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction opcoesPreco(p: any): OpcaoPreco[] {\n  const opts: OpcaoPreco[] = []\n  if (p.precoVarejo    > 0) opts.push({ key: 'varejo',    label: 'Varejo',    valor: p.precoVarejo })\n  if ((p.precoAtacadoA ?? p.precoAtacado) > 0) opts.push({ key: 'atacado_a', label: 'Atacado A', valor: p.precoAtacadoA ?? p.precoAtacado })\n  if (p.precoAtacadoB  > 0) opts.push({ key: 'atacado_b', label: 'Atacado B', valor: p.precoAtacadoB })\n  if (p.precoAtacadoC  > 0) opts.push({ key: 'atacado_c', label: 'Atacado C', valor: p.precoAtacadoC })\n  if (p.precoAtacadoD  > 0) opts.push({ key: 'atacado_d', label: 'Atacado D', valor: p.precoAtacadoD })\n  if (p.precoAtacadoE  > 0) opts.push({ key: 'atacado_e', label: 'Atacado E', valor: p.precoAtacadoE })\n  return opts\n}\n\nfunction precoByTipo(p: any, tipo: TipoPrecao): number {\n  switch (tipo) {\n    case 'atacado_a': return p.precoAtacadoA ?? p.precoAtacado ?? 0\n    case 'atacado_b': return p.precoAtacadoB ?? 0\n    case 'atacado_c': return p.precoAtacadoC ?? 0\n    case 'atacado_d': return p.precoAtacadoD ?? 0\n    case 'atacado_e': return p.precoAtacadoE ?? 0\n    default:          return p.precoVarejo ?? 0\n  }\n}\n\nfunction novoItem(): ItemVenda {\n  return {\n    _key: Math.random().toString(36).slice(2),\n    produtoId: 0, nomeProduto: '', quantidade: 1,\n    tipoPrecao: 'varejo', precoUnitario: 0, subtotal: 0,\n  }\n}\n\n// \u2500\u2500\u2500 Componente \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nexport default function VendasView({ tenantSlug }: Props) {\n  const qc        = useQueryClient()\n  const { toast } = useToast()\n  const router    = useRouter()\n  const api       = `/api/${tenantSlug}/vendas`\n\n  const tiposEntrega = useDominio(tenantSlug, 'tipo_entrega', ['Retirada', 'Entrega', 'Transportadora'])\n\n  const [showModal, setShowModal]         = useState(false)\n  const [confirmDelete, setConfirmDelete] = useState<{ id: number } | null>(null)\n  const [busca, setBusca]                 = useState('')\n  const [pageNum, setPageNum]             = useState(1)\n\n  // \u2500\u2500 Form state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  const [clienteId, setClienteId]             = useState('')\n  const [buscaCliente, setBuscaCliente]       = useState('')\n  const [clienteNomeDisplay, setClienteNomeDisplay] = useState('')\n  const [tipoEntrega, setTipoEntrega]         = useState('')\n  // Hor\u00e1rio local (n\u00e3o UTC) \u2014 evita defasagem de 3h no Brasil\n  const localNow = () => {\n    const d = new Date()\n    return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16)\n  }\n  const [vendidaEm, setVendidaEm] = useState(localNow())\n  const [dataEntrega, setDataEntrega]         = useState('')\n  const [enderecoEntrega, setEnderecoEntrega] = useState('')\n  const [vendedor, setVendedor]               = useState('')\n  const [observacao, setObservacao]           = useState('')\n  const [desconto, setDesconto]               = useState('0')\n  const [itens, setItens]                     = useState<ItemVenda[]>([novoItem()])\n  const [pagamentos, setPagamentos]           = useState<FormaPgto[]>([{ forma: 'PIX', valor: '' }])\n\n  const invalidate = () => qc.invalidateQueries({ queryKey: ['vendas', tenantSlug] })\n\n  // \u2500\u2500 Queries \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  const { data: vendasData, isLoading } = useQuery({\n    queryKey: ['vendas', tenantSlug, pageNum, busca],\n    queryFn:  async () => {\n      const p = new URLSearchParams({ page: String(pageNum), limit: '20' })\n      if (busca) p.set('busca', busca)\n      return (await fetch(`${api}?${p}`)).json()\n    },\n  })\n\n  const { data: kpisData } = useQuery({\n    queryKey: ['vendas-kpis', tenantSlug],\n    queryFn:  async () => (await fetch(`${api}?tipo=kpis`)).json(),\n    refetchInterval: 30000,\n  })\n\n  const { data: produtosRaw } = useQuery({\n    queryKey: ['produtos-venda', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/cadastros/produtos?limit=500`)).json(),\n  })\n\n  const { data: clientesRaw } = useQuery({\n    queryKey: ['clientes-select', tenantSlug, buscaCliente],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/cadastros/clientes?limit=8&search=${encodeURIComponent(buscaCliente)}`)).json(),\n    enabled:  buscaCliente.length > 1,\n  })\n\n  const { data: formasRaw } = useQuery({\n    queryKey: ['formas', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/cadastros/formas-pagamento`)).json(),\n  })\n\n  const { data: usuariosRaw } = useQuery({\n    queryKey: ['usuarios-select', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/cadastros/usuarios`)).json(),\n  })\n\n  // \u2500\u2500 Mutations \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  const criarMut = useMutation({\n    mutationFn: async () => {\n      const subtotalTotal = itens.reduce((a, i) => a + i.subtotal, 0)\n\n  // Auto-preenche o valor do primeiro pagamento com o total da venda\n  // quando ainda h\u00e1 s\u00f3 um pagamento e o valor est\u00e1 vazio ou \u00e9 0\n  const totalVendaCalc = Math.max(0, subtotalTotal - Math.round(parseFloat(desconto.replace(',', '.') || '0') * 100))\n      const descontoVal   = Math.round(parseFloat(desconto.replace(',', '.') || '0') * 100)\n      const total         = subtotalTotal - descontoVal\n      // Se o usu\u00e1rio n\u00e3o preencheu o valor do pagamento, usa o total da venda automaticamente\n      const pgtos = pagamentos\n        .map(p => {\n          const val = parseFloat(p.valor.replace(',', '.') || '0')\n          return { forma: p.forma, valor: Math.round(val * 100) }\n        })\n        .filter(p => p.valor > 0)\n\n      // Se ainda vazio, injeta o total no primeiro pagamento\n      const pgtosFinais = pgtos.length > 0\n        ? pgtos\n        : [{ forma: pagamentos[0]?.forma ?? 'PIX', valor: Math.max(0, subtotalTotal - descontoVal) }]\n\n      // \u2705 CORRE\u00c7\u00c3O: envia tipoPrecao, N\u00c3O envia precoUnitario\n      //    O servidor resolve o pre\u00e7o com base no tipoPrecao + dados do banco\n      const payload = {\n        clienteId:      clienteId ? Number(clienteId) : undefined,\n        tipoEntrega:    tipoEntrega || tiposEntrega[0],\n        vendidaEm:      new Date(vendidaEm).toISOString(),\n        dataEntrega:    dataEntrega ? new Date(dataEntrega).toISOString() : undefined,\n        enderecoEntrega: enderecoEntrega || undefined,\n        vendedor:       vendedor || undefined,\n        observacao:     observacao || undefined,\n        itens: itens\n          .filter(i => i.produtoId > 0)\n          .map(i => ({\n            produtoId:  i.produtoId,\n            quantidade: i.quantidade,\n            tipoPrecao: i.tipoPrecao,\n            // precoUnitario OMITIDO intencionalmente \u2014 servidor define\n          })),\n        desconto: descontoVal,\n        pagamentos: pgtosFinais,\n      }\n\n      const res = await fetch(api, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload),\n      })\n      const d = await res.json()\n      if (!res.ok) throw new Error(d.message)\n      return d\n    },\n    onSuccess: () => {\n      invalidate()\n      qc.invalidateQueries({ queryKey: ['vendas-kpis', tenantSlug] })\n      fecharModal()\n      toast('Venda registrada!')\n    },\n    onError: (e: any) => toast(e.message || 'Erro ao registrar venda.', 'error'),\n  })\n\n  const excluirMut = useMutation({\n    mutationFn: (id: number) => fetch(`${api}/${id}`, { method: 'DELETE' }).then(r => r.json()),\n    onSuccess: () => { invalidate(); toast('Venda exclu\u00edda.') },\n  })\n\n  // \u2500\u2500 Form helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function fecharModal() {\n    setShowModal(false)\n    setItens([novoItem()])\n    setPagamentos([{ forma: formasNomes[0] ?? 'PIX', valor: '' }])\n    setClienteId(''); setClienteNomeDisplay(''); setBuscaCliente(''); setTipoEntrega(''); setVendidaEm(new Date().toISOString().slice(0, 16))\n    setDataEntrega(''); setEnderecoEntrega(''); setVendedor(''); setObservacao(''); setDesconto('0'); setVendidaEm(localNow())\n  }\n\n  function updateItem(key: string, field: Partial<ItemVenda>) {\n    setItens(prev => prev.map(item => {\n      if (item._key !== key) return item\n      const updated = { ...item, ...field }\n      updated.subtotal = Math.round(updated.quantidade * updated.precoUnitario)\n      return updated\n    }))\n  }\n\n  function selecionarProduto(key: string, produto: any) {\n    const preco = produto.precoVarejo ?? 0\n    updateItem(key, {\n      produtoId: produto.produtoId,\n      nomeProduto: produto.nome,\n      tipoPrecao: 'varejo',\n      precoUnitario: preco,\n      _produto: produto,\n    })\n  }\n\n  function selecionarTipoPrecao(key: string, tipo: TipoPrecao, produto: any) {\n    const preco = precoByTipo(produto, tipo)\n    updateItem(key, { tipoPrecao: tipo, precoUnitario: preco })\n  }\n\n  function updatePgto(i: number, field: Partial<FormaPgto>) {\n    setPagamentos(prev => prev.map((p, idx) => idx === i ? { ...p, ...field } : p))\n  }\n\n  function exportCSV() {\n    const rows = vendas.map((v: any) => [\n      v.vendaId, fmtDateHora(v.vendidaEm),\n      v.clienteNome ?? 'Cons. Final',\n      v.tipoEntrega,\n      (v.total / 100).toFixed(2),\n    ])\n    const csv = [['ID', 'Data', 'Cliente', 'Entrega', 'Total'], ...rows]\n      .map(r => r.map((c: any) => `\"${c}\"`).join(',')).join('\\n')\n    const a = document.createElement('a')\n    a.href = URL.createObjectURL(new Blob(['\\uFEFF' + csv], { type: 'text/csv' }))\n    a.download = 'vendas.csv'\n    a.click()\n  }\n\n  // \u2500\u2500 Dados derivados \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  const produtos = Array.isArray(produtosRaw?.data?.data) ? produtosRaw.data.data\n    : Array.isArray(produtosRaw?.data) ? produtosRaw.data : []\n  const clientes = Array.isArray(clientesRaw?.data?.data) ? clientesRaw.data.data\n    : Array.isArray(clientesRaw?.data) ? clientesRaw.data : []\n  const formas     = Array.isArray(formasRaw?.data) ? formasRaw.data : []\n  const formasNomes = formas.map((f: any) => f.nome).filter(Boolean)\n  const usuarios = Array.isArray(usuariosRaw?.data?.data) ? usuariosRaw.data.data\n    : Array.isArray(usuariosRaw?.data) ? usuariosRaw.data : []\n\n  const vendas = Array.isArray(vendasData?.data?.data) ? vendasData.data.data\n    : Array.isArray(vendasData?.data) ? vendasData.data : []\n  const meta = vendasData?.data?.meta\n  const kpis = kpisData?.data\n\n  const subtotalTotal = itens.reduce((a, i) => a + i.subtotal, 0)\n\n  // Auto-preenche o valor do primeiro pagamento com o total da venda\n  // quando ainda h\u00e1 s\u00f3 um pagamento e o valor est\u00e1 vazio ou \u00e9 0\n  const descontoVal   = Math.round(parseFloat(desconto.replace(',', '.') || '0') * 100)\n  const totalVenda    = subtotalTotal - descontoVal\n  const totalPago     = pagamentos.reduce((a, p) => a + (parseFloat(p.valor.replace(',', '.') || '0') * 100), 0)\n  const troco         = totalPago > totalVenda ? totalPago - totalVenda : 0\n\n  // \u2500\u2500 Badge de canal \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function CanalBadge({ tipo }: { tipo: string }) {\n    const map: Record<string, { label: string; cls: string }> = {\n      retirada:       { label: 'Loja',     cls: 'bg-blue-100 text-blue-700' },\n      entrega:        { label: 'Delivery', cls: 'bg-green-100 text-green-700' },\n      transportadora: { label: 'B2B',      cls: 'bg-purple-100 text-purple-700' },\n    }\n    const cfg = map[tipo?.toLowerCase()] ?? { label: tipo, cls: 'bg-gray-100 text-gray-600' }\n    return (\n      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${cfg.cls}`}>\n        {cfg.label}\n      </span>\n    )\n  }\n\n  // \u2500\u2500 Render \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  return (\n    <div>\n      {/* \u2500\u2500 Header \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      <div className=\"flex items-center justify-between mb-6\">\n        <div>\n          <h1 className=\"text-2xl font-semibold text-gray-900\">Vendas</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">Loja, Delivery e B2B</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <Button variant=\"outline\" onClick={exportCSV}>\n            <Download size={14} className=\"mr-1.5\" /> CSV\n          </Button>\n          <Button onClick={() => setShowModal(true)}>\n            <Plus size={15} className=\"mr-1.5\" /> Nova Venda\n          </Button>\n        </div>\n      </div>\n\n      {/* \u2500\u2500 KPIs \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {kpis && (\n        <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3 mb-6\">\n          {[\n            { label: 'Receita hoje',   value: fmt(kpis.receitaHoje  ?? 0), color: 'text-green-600' },\n            { label: 'Receita do m\u00eas', value: fmt(kpis.receitaMes   ?? 0), color: 'text-green-600' },\n            { label: 'Vendas do m\u00eas',  value: String(kpis.qtdMes    ?? 0), color: 'text-gray-900' },\n            { label: 'Ticket m\u00e9dio',   value: fmt(kpis.ticketMedio  ?? 0), color: 'text-blue-600' },\n          ].map((k, i) => (\n            <div key={i} className=\"bg-white rounded-xl border border-gray-100 p-4\">\n              <p className=\"text-xs text-gray-400 mb-1\">{k.label}</p>\n              <p className={`text-xl font-bold ${k.color}`}>{k.value}</p>\n            </div>\n          ))}\n        </div>\n      )}\n\n      {/* \u2500\u2500 Filtro \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      <div className=\"flex gap-3 mb-4\">\n        <Input\n          placeholder=\"Buscar por cliente ou vendedor...\"\n          value={busca}\n          onChange={e => { setBusca(e.target.value); setPageNum(1) }}\n          className=\"max-w-xs h-9 text-sm\"\n        />\n      </div>\n\n      {/* \u2500\u2500 Tabela \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      <div className=\"bg-white rounded-xl border border-gray-100 overflow-hidden\">\n        <table className=\"w-full\">\n          <thead>\n            <tr className=\"border-b border-gray-100\">\n              {['Data', 'Cliente', 'Canal', 'Total', ''].map((h, i) => (\n                <th key={i} className={`text-left text-xs font-medium text-gray-400 px-4 py-3 ${i === 3 ? 'text-right' : ''}`}>{h}</th>\n              ))}\n            </tr>\n          </thead>\n          <tbody>\n            {isLoading ? (\n              <TableSkeleton rows={6} cols={5} />\n            ) : vendas.length === 0 ? (\n              <tr><td colSpan={5} className=\"px-4 py-12 text-center text-sm text-gray-400\">Nenhuma venda encontrada.</td></tr>\n            ) : vendas.map((v: any) => (\n              <tr key={v.vendaId} className=\"group border-b border-gray-50 hover:bg-gray-50/80 transition-colors\">\n                <td className=\"px-4 py-3 text-sm text-gray-500\">{fmtDateHora(v.vendidaEm)}</td>\n                <td className=\"px-4 py-3 text-sm font-medium text-gray-900\">{v.clienteNome ?? 'Consumidor Final'}</td>\n                <td className=\"px-4 py-3\"><CanalBadge tipo={v.tipoEntrega ?? 'retirada'} /></td>\n                <td className=\"px-4 py-3 text-right text-sm font-semibold text-green-600\">{fmt(v.total)}</td>\n                <td className=\"px-4 py-3\">\n                  <div className=\"flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity\">\n                    <button\n                      onClick={() => router.push(`/${tenantSlug}/vendas/${v.vendaId}`)}\n                      className=\"p-1 text-blue-400 hover:text-blue-600\"\n                    >\n                      <Eye size={14} />\n                    </button>\n                    <button\n                      onClick={() => setConfirmDelete({ id: v.vendaId })}\n                      className=\"p-1 text-gray-300 hover:text-red-500\"\n                    >\n                      <Trash2 size={14} />\n                    </button>\n                  </div>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n\n        {meta && meta.totalPages > 1 && (\n          <div className=\"flex items-center justify-between px-4 py-3 border-t border-gray-100\">\n            <p className=\"text-xs text-gray-400\">P\u00e1gina {meta.page} de {meta.totalPages} ({meta.total} vendas)</p>\n            <div className=\"flex gap-2\">\n              <Button variant=\"outline\" size=\"sm\" disabled={pageNum <= 1} onClick={() => setPageNum(p => p - 1)}>Anterior</Button>\n              <Button variant=\"outline\" size=\"sm\" disabled={pageNum >= meta.totalPages} onClick={() => setPageNum(p => p + 1)}>Pr\u00f3ximo</Button>\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* \u2500\u2500 Modal Nova Venda \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {showModal && (\n        <div className=\"fixed inset-0 z-50 flex items-center justify-center\" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>\n          <div className=\"bg-white rounded-2xl shadow-2xl w-full max-w-3xl mx-4 max-h-[92vh] flex flex-col\">\n\n            {/* Header do modal */}\n            <div className=\"flex items-center justify-between p-6 border-b border-gray-100 sticky top-0 bg-white z-10 rounded-t-2xl\">\n              <h2 className=\"text-lg font-semibold\">Nova Venda</h2>\n              <button onClick={fecharModal} className=\"text-gray-400 hover:text-gray-600\"><X size={18} /></button>\n            </div>\n\n            <div className=\"flex-1 overflow-y-auto p-6 space-y-5\">\n\n              {/* Info geral */}\n              <div className=\"grid grid-cols-2 md:grid-cols-3 gap-3\">\n                <div>\n                  <Label>Cliente</Label>\n                  <select\n                    value={clienteId}\n                    onChange={e => {\n                      setClienteId(e.target.value)\n                      // Auto-preenche endere\u00e7o se dispon\u00edvel\n                      const c = clientes.find((x: any) => String(x.clienteId) === e.target.value)\n                      if (c?.endereco) setEnderecoEntrega(`${c.endereco}${c.numero ? ', ' + c.numero : ''} \u2014 ${c.cidade}/${c.uf}`)\n                    }}\n                    className=\"mt-1 w-full h-9 rounded-lg border border-gray-200 px-3 text-sm focus:outline-none\"\n                  >\n                    <option value=\"\">Consumidor Final</option>\n                    {clientes.map((c: any) => (\n                      <option key={c.clienteId} value={c.clienteId}>{c.nomeCompleto}</option>\n                    ))}\n                  </select>\n                </div>\n                <div>\n                  <Label>Canal de Venda</Label>\n                  <select\n                    value={tipoEntrega}\n                    onChange={e => setTipoEntrega(e.target.value)}\n                    className=\"mt-1 w-full h-9 rounded-lg border border-gray-200 px-3 text-sm focus:outline-none\"\n                  >\n                    {tiposEntrega.map(t => <option key={t} value={t}>{t}</option>)}\n                  </select>\n                </div>\n                <div>\n                  <Label>Data da Venda</Label>\n                  <Input type=\"datetime-local\" value={vendidaEm} onChange={e => setVendidaEm(e.target.value)} className=\"mt-1 h-9 text-sm\" />\n                </div>\n                <div>\n                  <Label>Data de Entrega</Label>\n                  <Input type=\"date\" value={dataEntrega} onChange={e => setDataEntrega(e.target.value)} className=\"mt-1 h-9 text-sm\" />\n                </div>\n                <div>\n                  <Label>Vendedor</Label>\n                  <select\n                    value={vendedor}\n                    onChange={e => setVendedor(e.target.value)}\n                    className=\"mt-1 w-full h-9 rounded-lg border border-gray-200 px-3 text-sm focus:outline-none\"\n                  >\n                    <option value=\"\">Selecionar...</option>\n                    {usuarios.map((u: any) => (\n                      <option key={u.usuarioId} value={u.nome}>{u.nome}</option>\n                    ))}\n                  </select>\n                </div>\n                <div>\n                  <Label>Endere\u00e7o Entrega</Label>\n                  <Input value={enderecoEntrega} onChange={e => setEnderecoEntrega(e.target.value)} className=\"mt-1 h-9 text-sm\" />\n                </div>\n              </div>\n\n              <div>\n                <Label>Observa\u00e7\u00e3o</Label>\n                <Input value={observacao} onChange={e => setObservacao(e.target.value)} className=\"mt-1 h-9 text-sm\" />\n              </div>\n\n              {/* \u2500\u2500 Itens \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n              <div>\n                <div className=\"flex items-center justify-between mb-3\">\n                  <p className=\"text-sm font-semibold text-gray-700\">Itens da Venda</p>\n                  <Button size=\"sm\" variant=\"outline\" onClick={() => setItens(prev => [...prev, novoItem()])}>\n                    <Plus size={13} className=\"mr-1\" /> Adicionar produto\n                  </Button>\n                </div>\n\n                <div className=\"border border-gray-100 rounded-xl overflow-hidden\">\n                  <table className=\"w-full\">\n                    <thead>\n                      <tr className=\"border-b border-gray-100 bg-gray-50\">\n                        <th className=\"text-left text-xs font-medium text-gray-400 px-3 py-2.5 w-44\">Produto</th>\n                        <th className=\"text-left text-xs font-medium text-gray-400 px-3 py-2.5\">Tabela de Pre\u00e7o</th>\n                        <th className=\"text-right text-xs font-medium text-gray-400 px-3 py-2.5 w-20\">Qtd</th>\n                        <th className=\"text-right text-xs font-medium text-gray-400 px-3 py-2.5 w-28\">Pre\u00e7o Unit.</th>\n                        <th className=\"text-right text-xs font-medium text-gray-400 px-3 py-2.5 w-28\">Subtotal</th>\n                        <th className=\"w-8\" />\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {itens.map(item => {\n                        const opts = item._produto ? opcoesPreco(item._produto) : []\n                        return (\n                          <tr key={item._key} className=\"border-b border-gray-50 last:border-0\">\n                            {/* Produto */}\n                            <td className=\"px-3 py-2\">\n                              <select\n                                value={item.produtoId || ''}\n                                onChange={e => {\n                                  const p = produtos.find((x: any) => x.produtoId === Number(e.target.value))\n                                  if (p) selecionarProduto(item._key, p)\n                                }}\n                                className=\"w-full h-8 rounded-lg border border-gray-200 px-2 text-sm focus:outline-none\"\n                              >\n                                <option value=\"\">Selecionar...</option>\n                                {produtos.map((p: any) => (\n                                  <option key={p.produtoId} value={p.produtoId}>{p.nome}</option>\n                                ))}\n                              </select>\n                            </td>\n\n                            {/* Tabela de pre\u00e7o \u2014 \u2705 CORRE\u00c7\u00c3O: controla tipoPrecao */}\n                            <td className=\"px-3 py-2\">\n                              {opts.length > 0 ? (\n                                <select\n                                  value={item.tipoPrecao}\n                                  onChange={e => selecionarTipoPrecao(item._key, e.target.value as TipoPrecao, item._produto)}\n                                  className=\"w-full h-8 rounded-lg border border-gray-200 px-2 text-xs focus:outline-none\"\n                                >\n                                  {opts.map(o => (\n                                    <option key={o.key} value={o.key}>\n                                      {o.label} \u2014 {fmt(o.valor)}\n                                    </option>\n                                  ))}\n                                </select>\n                              ) : (\n                                <span className=\"text-xs text-gray-400 px-2\">\u2014</span>\n                              )}\n                            </td>\n\n                            {/* Quantidade */}\n                            <td className=\"px-3 py-2\">\n                              <Input\n                                type=\"number\" min=\"1\" step=\"1\"\n                                value={item.quantidade}\n                                onChange={e => updateItem(item._key, { quantidade: Math.max(1, Number(e.target.value)) })}\n                                className=\"h-8 text-sm text-right\"\n                              />\n                            </td>\n\n                            {/* Pre\u00e7o unit. \u2014 somente exibi\u00e7\u00e3o, n\u00e3o edit\u00e1vel */}\n                            <td className=\"px-3 py-2 text-right text-sm text-gray-600\">\n                              {item.precoUnitario > 0 ? fmt(item.precoUnitario) : '\u2014'}\n                            </td>\n\n                            {/* Subtotal */}\n                            <td className=\"px-3 py-2 text-right text-sm font-semibold text-gray-900\">\n                              {item.subtotal > 0 ? fmt(item.subtotal) : '\u2014'}\n                            </td>\n\n                            {/* Remover */}\n                            <td className=\"px-3 py-2\">\n                              {itens.length > 1 && (\n                                <button\n                                  onClick={() => setItens(prev => prev.filter(i => i._key !== item._key))}\n                                  className=\"text-gray-300 hover:text-red-500\"\n                                >\n                                  <X size={14} />\n                                </button>\n                              )}\n                            </td>\n                          </tr>\n                        )\n                      })}\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n\n              {/* \u2500\u2500 Totais + Pagamento \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n              <div className=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n\n                {/* Pagamento */}\n                <div className=\"space-y-2\">\n                  <p className=\"text-sm font-semibold text-gray-700\">Pagamento</p>\n                  {pagamentos.map((p, i) => (\n                    <div key={i} className=\"flex gap-2 items-center\">\n                      <select\n                        value={p.forma}\n                        onChange={e => updatePgto(i, { forma: e.target.value })}\n                        className=\"h-9 rounded-lg border border-gray-200 px-3 text-sm focus:outline-none flex-1\"\n                      >\n                        {(formasNomes.length > 0\n                          ? formasNomes\n                          : ['Dinheiro', 'PIX', 'Cart\u00e3o D\u00e9bito', 'Cart\u00e3o Cr\u00e9dito', 'Boleto']\n                        ).map((f: string) => <option key={f} value={f}>{f}</option>)}\n                      </select>\n                      <Input\n                        type=\"number\" min=\"0\" step=\"0.01\"\n                        value={p.valor}\n                        onChange={e => updatePgto(i, { valor: e.target.value })}\n                        className=\"h-9 text-sm w-32\"\n                        placeholder=\"0,00\"\n                      />\n                      {pagamentos.length > 1 && (\n                        <button\n                          onClick={() => setPagamentos(prev => prev.filter((_, idx) => idx !== i))}\n                          className=\"text-gray-300 hover:text-red-500\"\n                        >\n                          <X size={14} />\n                        </button>\n                      )}\n                    </div>\n                  ))}\n                  <Button\n                    size=\"sm\" variant=\"outline\"\n                    onClick={() => setPagamentos(prev => [...prev, { forma: formasNomes[0] ?? 'PIX', valor: '' }])}\n                  >\n                    <Plus size={12} className=\"mr-1\" /> Outra forma\n                  </Button>\n                </div>\n\n                {/* Resumo */}\n                <div className=\"bg-gray-50 rounded-xl p-4 space-y-2 text-sm\">\n                  <div className=\"flex justify-between\">\n                    <span className=\"text-gray-500\">Subtotal</span>\n                    <span className=\"font-medium\">{fmt(subtotalTotal)}</span>\n                  </div>\n                  <div className=\"flex items-center justify-between\">\n                    <span className=\"text-gray-500\">Desconto (R$)</span>\n                    <Input\n                      type=\"number\" min=\"0\" step=\"0.01\"\n                      value={desconto}\n                      onChange={e => setDesconto(e.target.value)}\n                      className=\"h-7 text-sm w-24 text-right\"\n                    />\n                  </div>\n                  <div className=\"flex justify-between border-t border-gray-200 pt-2 font-bold text-base\">\n                    <span>Total</span>\n                    <span className=\"text-green-600\">{fmt(totalVenda)}</span>\n                  </div>\n                  {troco > 0 && (\n                    <div className=\"flex justify-between text-amber-600 font-semibold\">\n                      <span>Troco</span>\n                      <span>{fmt(troco)}</span>\n                    </div>\n                  )}\n                </div>\n              </div>\n            </div>\n\n            {/* Footer do modal */}\n            <div className=\"flex justify-end gap-3 p-6 border-t border-gray-100 flex-shrink-0\">\n              <Button variant=\"outline\" onClick={fecharModal}>Cancelar</Button>\n              <Button\n                onClick={() => criarMut.mutate()}\n                disabled={itens.every(i => !i.produtoId) || criarMut.isPending}\n              >\n                {criarMut.isPending ? 'Registrando...' : 'Registrar Venda'}\n              </Button>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* \u2500\u2500 Confirm delete \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */}\n      {confirmDelete && (\n        <ConfirmModal\n          title=\"Excluir venda\"\n          message=\"Esta a\u00e7\u00e3o n\u00e3o pode ser desfeita.\"\n          confirmLabel=\"Excluir\"\n          danger\n          onConfirm={() => { excluirMut.mutate(confirmDelete.id); setConfirmDelete(null) }}\n          onCancel={() => setConfirmDelete(null)}\n        />\n      )}\n    </div>\n  )\n}\n"],
  ["components/modules/producao/ProducaoView.tsx", "'use client'\nimport { useState } from 'react'\nimport { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'\nimport { ChevronLeft, ChevronRight, Factory, AlertTriangle, CheckCircle, X } from 'lucide-react'\nimport { Button } from '@/components/ui/button'\nimport { Input } from '@/components/ui/input'\nimport { Label } from '@/components/ui/label'\n\ninterface Props { tenantSlug: string }\n\nfunction getWeekDates(offset = 0) {\n  const now = new Date()\n  const day = now.getDay()\n  const mon = new Date(now)\n  mon.setDate(now.getDate() - (day === 0 ? 6 : day - 1) + offset * 7)\n  return Array.from({ length: 6 }, (_, i) => {\n    const d = new Date(mon); d.setDate(mon.getDate() + i); return d\n  })\n}\n\nfunction fmtDate(d: Date) { return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) }\nfunction isoDate(d: Date) { return d.toISOString().slice(0, 10) }\nconst DIAS = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'S\u00e1b']\n\ntype CelulaKey = { produtoId: number; data: string; tipo: 'producao' | 'pedido' }\n\nexport default function ProducaoView({ tenantSlug }: Props) {\n  const qc = useQueryClient()\n  const [weekOffset, setWeekOffset]         = useState(0)\n  const [editandoCelula, setEditandoCelula] = useState<CelulaKey | null>(null)\n  const [valorCelula, setValorCelula]       = useState('')\n  const [showPrevisao, setShowPrevisao]     = useState(false)\n  const [showBaixa, setShowBaixa]           = useState(false)\n  const [produtoBaixa, setProdutoBaixa]     = useState<any>(null)\n  const [qtdBaixa, setQtdBaixa]             = useState('')\n  const [previewBaixa, setPreviewBaixa]     = useState<any>(null)\n  const [loadingBaixa, setLoadingBaixa]     = useState(false)\n  const [resultadoBaixa, setResultadoBaixa] = useState<any>(null)\n\n  const dias   = getWeekDates(weekOffset)\n  const inicio = isoDate(dias[0])\n  const fim    = isoDate(dias[5])\n\n  const { data: gradeData } = useQuery({\n    queryKey: ['producao-grade', tenantSlug, inicio, fim],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/producao/grade?inicio=${inicio}&fim=${fim}`)).json(),\n  })\n\n  const { data: previsaoData } = useQuery({\n    queryKey: ['producao-previsao', tenantSlug, inicio, fim],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/producao/previsao?inicio=${inicio}&fim=${fim}`)).json(),\n    enabled:  showPrevisao,\n  })\n\n  // Previs\u00e3o semanal necess\u00e1ria \u2014 m\u00e9dia hist\u00f3rica de todos os meses anteriores \u00f7 4\n  const { data: prevSemanalData } = useQuery({\n    queryKey: ['previsao-semanal', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/metas?tipo=previsao&mes=${new Date().getMonth() + 1}&ano=${new Date().getFullYear()}&mesesHistorico=12`)).json(),\n    staleTime: 300000, // 5 min\n  })\n\n  const { data: produtosData } = useQuery({\n    queryKey: ['produtos-select', tenantSlug],\n    queryFn:  async () => (await fetch(`/api/${tenantSlug}/cadastros/produtos`)).json(),\n  })\n\n  const salvarCelulaMut = useMutation({\n    mutationFn: ({ produtoId, data, quantidade, tipo }: any) => fetch(`/api/${tenantSlug}/producao/grade`, {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ produtoId, dataProducao: data, quantidade: Number(quantidade), tipo }),\n    }).then(r => r.json()),\n    onSuccess: () => qc.invalidateQueries({ queryKey: ['producao-grade', tenantSlug] }),\n  })\n\n  function iniciarEdicao(produtoId: number, data: string, tipo: 'producao' | 'pedido', valorAtual: number) {\n    setEditandoCelula({ produtoId, data, tipo })\n    setValorCelula(String(valorAtual || ''))\n  }\n\n  function salvarCelula(produtoId: number, data: string, tipo: 'producao' | 'pedido') {\n    salvarCelulaMut.mutate({ produtoId, data, quantidade: valorCelula || '0', tipo })\n    setEditandoCelula(null)\n  }\n\n  const grade        = gradeData?.data ?? gradeData ?? {}\n  const produtos     = Array.isArray(grade.produtos) ? grade.produtos : []\n  const celulas      = grade.grade ?? {}         // grade[produtoId][data] = qtd produ\u00e7\u00e3o\n  const celulasPed   = grade.pedidos ?? {}       // pedidos[produtoId][data] = qtd pedido\n\n  const previsao = Array.isArray(previsaoData?.data) ? previsaoData.data\n    : Array.isArray(previsaoData) ? previsaoData : []\n\n  const todosProdutos = Array.isArray(produtosData?.data?.data) ? produtosData.data.data\n    : Array.isArray(produtosData?.data) ? produtosData.data : []\n\n  // Mapa de previs\u00e3o semanal por produto (m\u00e9dia hist\u00f3rica \u00f7 4)\n  const prevSemanal: Record<number, number> = {}\n  const prevProdutos = prevSemanalData?.data?.produtos ?? []\n  for (const p of prevProdutos) {\n    prevSemanal[p.produtoId] = Math.ceil((p.mediaVendas ?? 0) / 4)\n  }\n\n  async function verPreviewBaixa() {\n    if (!produtoBaixa || !qtdBaixa) return\n    setLoadingBaixa(true)\n    try {\n      const res = await fetch(`/api/${tenantSlug}/producao/baixar-insumos`, {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ produtoId: produtoBaixa.produtoId, quantidade: Number(qtdBaixa), confirmar: false }),\n      })\n      const data = await res.json()\n      setPreviewBaixa(data?.data ?? data)\n    } finally { setLoadingBaixa(false) }\n  }\n\n  async function confirmarBaixa() {\n    if (!produtoBaixa || !qtdBaixa) return\n    setLoadingBaixa(true)\n    try {\n      const res = await fetch(`/api/${tenantSlug}/producao/baixar-insumos`, {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ produtoId: produtoBaixa.produtoId, quantidade: Number(qtdBaixa), confirmar: true }),\n      })\n      const data = await res.json()\n      setResultadoBaixa(data?.data ?? data)\n      qc.invalidateQueries({ queryKey: ['estoque-insumos', tenantSlug] })\n    } finally { setLoadingBaixa(false) }\n  }\n\n  function fecharBaixa() {\n    setShowBaixa(false); setProdutoBaixa(null); setQtdBaixa('')\n    setPreviewBaixa(null); setResultadoBaixa(null)\n  }\n\n  function CelulaEditavel({ produtoId, data, tipo, valor, cor }: { produtoId: number; data: string; tipo: 'producao' | 'pedido'; valor: number; cor: string }) {\n    const isEdit = editandoCelula?.produtoId === produtoId && editandoCelula?.data === data && editandoCelula?.tipo === tipo\n    if (isEdit) {\n      return (\n        <input type=\"number\" min=\"0\" value={valorCelula}\n          onChange={e => setValorCelula(e.target.value)}\n          onBlur={() => salvarCelula(produtoId, data, tipo)}\n          onKeyDown={e => {\n            if (e.key === 'Enter') salvarCelula(produtoId, data, tipo)\n            if (e.key === 'Escape') setEditandoCelula(null)\n          }}\n          className=\"w-10 h-6 text-center text-xs border border-green-400 rounded focus:outline-none\" autoFocus />\n      )\n    }\n    return (\n      <button onClick={() => iniciarEdicao(produtoId, data, tipo, valor)}\n        className={`w-10 h-6 rounded text-xs font-medium transition-colors ${valor > 0 ? `${cor} hover:opacity-80` : 'text-gray-200 hover:bg-gray-100'}`}>\n        {valor > 0 ? valor : '\u2014'}\n      </button>\n    )\n  }\n\n  // Totais por coluna\n  const totaisPedDia: Record<string, number> = {}\n  const totaisPrevDia: Record<string, number> = {}\n  for (const dia of dias) {\n    const d = isoDate(dia)\n    totaisPedDia[d]  = produtos.reduce((a: number, p: any) => a + (celulasPed?.[p.produtoId]?.[d] ?? 0), 0)\n    totaisPrevDia[d] = produtos.reduce((a: number, p: any) => a + (celulas?.[p.produtoId]?.[d] ?? 0), 0)\n  }\n\n  return (\n    <div>\n      <div className=\"flex items-center justify-between mb-6\">\n        <div>\n          <h1 className=\"text-2xl font-semibold text-gray-900\">Produ\u00e7\u00e3o</h1>\n          <p className=\"text-sm text-gray-400 mt-0.5\">{fmtDate(dias[0])} \u2013 {fmtDate(dias[5])}</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <Button variant=\"outline\" size=\"sm\" onClick={() => setShowPrevisao(!showPrevisao)}>\n            {showPrevisao ? 'Ocultar Previs\u00e3o Insumos' : 'Ver Previs\u00e3o de Insumos'}\n          </Button>\n          <Button onClick={() => setShowBaixa(true)}>\n            <Factory size={14} className=\"mr-1.5\" /> Registrar Produ\u00e7\u00e3o\n          </Button>\n        </div>\n      </div>\n\n      {/* Navega\u00e7\u00e3o semana */}\n      <div className=\"flex items-center gap-3 mb-4\">\n        <button onClick={() => setWeekOffset(w => w - 1)} className=\"p-1.5 rounded-lg border border-gray-200 hover:bg-gray-50\"><ChevronLeft size={16} /></button>\n        <span className=\"text-sm font-medium text-gray-700 min-w-48 text-center\">\n          {dias[0].toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' })} \u2013 {dias[5].toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' })}\n        </span>\n        <button onClick={() => setWeekOffset(w => w + 1)} className=\"p-1.5 rounded-lg border border-gray-200 hover:bg-gray-50\"><ChevronRight size={16} /></button>\n        {weekOffset !== 0 && <button onClick={() => setWeekOffset(0)} className=\"text-xs text-blue-600 hover:underline\">Esta semana</button>}\n      </div>\n\n      {/* Grade */}\n      <div className=\"bg-white rounded-xl border border-gray-100 overflow-hidden\">\n        <div className=\"overflow-x-auto\">\n          <table className=\"w-full min-w-max text-xs\">\n            <thead>\n              <tr className=\"border-b border-gray-100 bg-gray-50\">\n                <th className=\"text-left text-xs font-medium text-gray-500 px-3 py-2 w-36 sticky left-0 bg-gray-50\">Produto</th>\n                <th className=\"text-center text-xs font-medium text-gray-500 px-2 py-2 w-16\">Estoque</th>\n                {DIAS.map((d, i) => (\n                  <th key={d} className=\"text-center text-xs font-medium text-gray-400 px-0 py-1\" colSpan={2}>\n                    <div className=\"font-semibold text-gray-600\">{d}</div>\n                    <div className=\"text-[10px] text-gray-400\">{fmtDate(dias[i])}</div>\n                    <div className=\"grid grid-cols-2 text-[9px] text-gray-300 mt-0.5\">\n                      <span className=\"text-blue-400\">Ped</span>\n                      <span className=\"text-green-500\">PP</span>\n                    </div>\n                  </th>\n                ))}\n                <th className=\"text-center text-xs font-medium text-blue-600 px-2 py-2 w-20\">Total Ped.</th>\n                <th className=\"text-center text-xs font-medium text-gray-500 px-2 py-2 w-20\">Prev. Est.</th>\n                <th className=\"text-center text-xs font-bold text-orange-600 px-2 py-2 w-24 bg-orange-50\">Prod. Semanal Necess\u00e1ria</th>\n              </tr>\n            </thead>\n            <tbody>\n              {produtos.length === 0 ? (\n                <tr><td colSpan={3 + DIAS.length * 2 + 3} className=\"px-4 py-12 text-center text-sm text-gray-400\">Nenhum produto cadastrado.</td></tr>\n              ) : produtos.map((p: any) => {\n                const estoque = p.estoqueAtual ?? 0\n                let totalPed = 0, totalPrev = 0\n\n                return (\n                  <tr key={p.produtoId} className=\"border-b border-gray-50 hover:bg-gray-50/30 last:border-0\">\n                    <td className=\"px-3 py-2 text-xs font-medium text-gray-900 sticky left-0 bg-white whitespace-nowrap max-w-[140px] truncate\">{p.nome}</td>\n                    <td className=\"px-2 py-2 text-center\">\n                      <span className={`text-xs font-semibold ${estoque <= (p.estoqueMinimo ?? 0) ? 'text-red-600' : 'text-gray-700'}`}>{estoque}</span>\n                    </td>\n                    {dias.map(dia => {\n                      const d = isoDate(dia)\n                      const ped  = celulasPed?.[p.produtoId]?.[d] ?? 0\n                      const prev = celulas?.[p.produtoId]?.[d] ?? 0\n                      totalPed  += ped\n                      totalPrev += prev\n                      return (\n                        <>\n                          <td key={`ped-${d}`} className=\"px-0.5 py-1 text-center\">\n                            <CelulaEditavel produtoId={p.produtoId} data={d} tipo=\"pedido\" valor={ped} cor=\"bg-blue-100 text-blue-700\" />\n                          </td>\n                          <td key={`prev-${d}`} className=\"px-0.5 py-1 text-center\">\n                            <CelulaEditavel produtoId={p.produtoId} data={d} tipo=\"producao\" valor={prev} cor=\"bg-green-100 text-green-700\" />\n                          </td>\n                        </>\n                      )\n                    })}\n                    <td className=\"px-2 py-2 text-center\">\n                      <span className={`text-xs font-semibold ${totalPed > 0 ? 'text-blue-700' : 'text-gray-200'}`}>{totalPed > 0 ? totalPed : '\u2014'}</span>\n                    </td>\n                    <td className=\"px-2 py-2 text-center\">\n                      {(() => {\n                        const prevEst = estoque + totalPrev - totalPed\n                        return <span className={`text-xs font-semibold ${prevEst < 0 ? 'text-red-600' : 'text-gray-700'}`}>{prevEst}</span>\n                      })()}\n                    </td>\n                    <td className=\"px-2 py-2 text-center bg-orange-50\">\n                      {(() => {\n                        const ps = prevSemanal[p.produtoId] ?? 0\n                        return <span className={`text-xs font-bold ${ps > 0 ? 'text-orange-600' : 'text-gray-300'}`}>{ps > 0 ? ps : '\u2014'}</span>\n                      })()}\n                    </td>\n                  </tr>\n                )\n              })}\n            </tbody>\n            {/* Totais */}\n            {produtos.length > 0 && (\n              <tfoot>\n                <tr className=\"border-t-2 border-gray-200 bg-gray-50\">\n                  <td className=\"px-3 py-2 text-xs font-bold text-gray-600 sticky left-0 bg-gray-50\">Total Geral ({produtos.length})</td>\n                  <td className=\"px-2 py-2 text-center text-xs font-bold text-gray-700\">\n                    {produtos.reduce((a: number, p: any) => a + (p.estoqueAtual ?? 0), 0)}\n                  </td>\n                  {dias.map(dia => {\n                    const d = isoDate(dia)\n                    return (\n                      <>\n                        <td key={`tot-ped-${d}`} className=\"px-0.5 py-2 text-center text-xs font-bold text-blue-600\">{totaisPedDia[d] > 0 ? totaisPedDia[d] : '\u2014'}</td>\n                        <td key={`tot-prev-${d}`} className=\"px-0.5 py-2 text-center text-xs font-bold text-green-600\">{totaisPrevDia[d] > 0 ? totaisPrevDia[d] : '\u2014'}</td>\n                      </>\n                    )\n                  })}\n                  <td className=\"px-2 py-2 text-center text-xs font-bold text-blue-700\">\n                    {Object.values(totaisPedDia).reduce((a: number, v) => a + v, 0) || '\u2014'}\n                  </td>\n                  <td className=\"px-2 py-2 text-center text-xs text-gray-400\">\u2014</td>\n                  <td className=\"px-2 py-2 text-center text-xs font-bold text-orange-600 bg-orange-50\">\n                    {Object.values(prevSemanal).reduce((a, v) => a + v, 0) || '\u2014'}\n                  </td>\n                </tr>\n              </tfoot>\n            )}\n          </table>\n        </div>\n        {/* Legenda */}\n        <div className=\"px-4 py-2 border-t border-gray-100 flex gap-4 flex-wrap text-[10px] text-gray-400\">\n          <span className=\"flex items-center gap-1\"><span className=\"w-3 h-3 rounded bg-blue-100 inline-block\" /> Pedido \u2014 edit\u00e1vel</span>\n          <span className=\"flex items-center gap-1\"><span className=\"w-3 h-3 rounded bg-green-100 inline-block\" /> Previs\u00e3o de Produ\u00e7\u00e3o (PP) \u2014 edit\u00e1vel</span>\n          <span className=\"flex items-center gap-1\"><span className=\"w-3 h-3 rounded bg-orange-100 inline-block\" /> Prod. Necess\u00e1ria = m\u00e9dia hist\u00f3rica \u00f7 4 semanas</span>\n          <span className=\"text-gray-300\">Prev. Est. = Estoque + Produ\u00e7\u00e3o \u2212 Pedidos</span>\n        </div>\n      </div>\n\n      {/* Previs\u00e3o de Insumos */}\n      {showPrevisao && (\n        <div className=\"mt-4 bg-white rounded-xl border border-gray-100 overflow-hidden\">\n          <div className=\"px-4 py-3 border-b border-gray-100 bg-gray-50\">\n            <h3 className=\"text-sm font-semibold text-gray-700\">Previs\u00e3o de Insumos \u2014 semana atual</h3>\n          </div>\n          {previsao.length === 0 ? (\n            <p className=\"px-4 py-8 text-center text-sm text-gray-400\">Sem produ\u00e7\u00e3o planejada ou fichas t\u00e9cnicas n\u00e3o cadastradas.</p>\n          ) : (\n            <table className=\"w-full\">\n              <thead>\n                <tr className=\"border-b border-gray-100\">\n                  {['Insumo', 'Necess\u00e1rio', 'Estoque Atual', 'Situa\u00e7\u00e3o'].map((h, i) => (\n                    <th key={h} className={`text-${i === 0 ? 'left' : 'center'} text-xs font-medium text-gray-400 px-4 py-3`}>{h}</th>\n                  ))}\n                </tr>\n              </thead>\n              <tbody>\n                {previsao.map((item: any, i: number) => (\n                  <tr key={i} className={`border-b border-gray-50 ${!item.suficiente ? 'bg-red-50/30' : ''}`}>\n                    <td className=\"px-4 py-2.5 text-sm font-medium text-gray-900\">{item.nomeInsumo ?? item.nome}</td>\n                    <td className=\"px-4 py-2.5 text-center text-sm text-gray-600\">{parseFloat(String(item.totalNecessario ?? item.necessario ?? 0)).toFixed(3)} {item.unidade}</td>\n                    <td className=\"px-4 py-2.5 text-center text-sm\">\n                      <span className={item.suficiente ? 'text-green-600 font-semibold' : 'text-red-600 font-semibold'}>{item.estoqueAtual}</span>\n                    </td>\n                    <td className=\"px-4 py-2.5 text-center\">\n                      {item.suficiente\n                        ? <span className=\"text-xs text-green-600 flex items-center justify-center gap-1\"><CheckCircle size={12} /> OK</span>\n                        : <span className=\"text-xs text-red-600 flex items-center justify-center gap-1\"><AlertTriangle size={12} /> Insuficiente</span>}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          )}\n        </div>\n      )}\n\n      {/* Modal Registrar Produ\u00e7\u00e3o */}\n      {showBaixa && (\n        <div className=\"fixed inset-0 z-50 flex items-center justify-center\" style={{ backgroundColor: 'rgba(0,0,0,0.4)' }}>\n          <div className=\"bg-white rounded-2xl shadow-xl w-full max-w-lg mx-4 max-h-[90vh] overflow-y-auto\">\n            <div className=\"flex items-center justify-between p-6 border-b border-gray-100\">\n              <div>\n                <h2 className=\"text-lg font-semibold\">Registrar Produ\u00e7\u00e3o</h2>\n                <p className=\"text-sm text-gray-400 mt-0.5\">Baixa autom\u00e1tica de insumos conforme ficha t\u00e9cnica</p>\n              </div>\n              <button onClick={fecharBaixa} className=\"text-gray-400 hover:text-gray-600\"><X size={18} /></button>\n            </div>\n            <div className=\"p-6 space-y-4\">\n              {!resultadoBaixa ? (\n                <>\n                  <div>\n                    <Label>Produto *</Label>\n                    <select value={produtoBaixa?.produtoId ?? ''}\n                      onChange={e => { const p = todosProdutos.find((x: any) => x.produtoId === Number(e.target.value)); setProdutoBaixa(p ?? null); setPreviewBaixa(null) }}\n                      className=\"mt-1 w-full h-9 rounded-lg border border-gray-200 px-3 text-sm focus:outline-none\">\n                      <option value=\"\">Selecionar produto...</option>\n                      {todosProdutos.map((p: any) => <option key={p.produtoId} value={p.produtoId}>{p.nome}</option>)}\n                    </select>\n                  </div>\n                  <div>\n                    <Label>Quantidade produzida *</Label>\n                    <Input type=\"number\" min=\"1\" value={qtdBaixa} onChange={e => { setQtdBaixa(e.target.value); setPreviewBaixa(null) }} className=\"mt-1\" placeholder=\"Ex: 10\" />\n                  </div>\n                  {!previewBaixa && (\n                    <Button variant=\"outline\" className=\"w-full\" onClick={verPreviewBaixa} disabled={!produtoBaixa || !qtdBaixa || loadingBaixa}>\n                      {loadingBaixa ? 'Calculando...' : 'Ver insumos que ser\u00e3o consumidos'}\n                    </Button>\n                  )}\n                  {previewBaixa && (\n                    <>\n                      {!previewBaixa.temFicha ? (\n                        <div className=\"bg-amber-50 border border-amber-200 rounded-lg p-4\">\n                          <p className=\"text-sm text-amber-700\">{previewBaixa.message}</p>\n                        </div>\n                      ) : (\n                        <>\n                          <table className=\"w-full border border-gray-100 rounded-lg overflow-hidden\">\n                            <thead><tr className=\"bg-gray-50\">\n                              {['Insumo','Consumo','Estoque','Ficar\u00e1'].map((h,i) => <th key={h} className={`text-xs font-medium text-gray-400 px-3 py-2 ${i===0?'text-left':'text-center'}`}>{h}</th>)}\n                            </tr></thead>\n                            <tbody>\n                              {previewBaixa.itens?.map((item: any, i: number) => (\n                                <tr key={i} className={`border-t border-gray-50 ${!item.suficiente ? 'bg-red-50/30' : ''}`}>\n                                  <td className=\"px-3 py-2 text-sm font-medium text-gray-900\">{item.nomeInsumo}</td>\n                                  <td className=\"px-3 py-2 text-center text-sm\">{item.qtdNecessaria.toFixed(3)} {item.unidade}</td>\n                                  <td className=\"px-3 py-2 text-center text-sm\">{item.estoqueAtual.toFixed(3)}</td>\n                                  <td className=\"px-3 py-2 text-center text-sm\"><span className={item.suficiente ? 'text-green-600 font-semibold' : 'text-red-600 font-semibold'}>{Math.max(0, item.estoqueRestante).toFixed(3)}</span></td>\n                                </tr>\n                              ))}\n                            </tbody>\n                          </table>\n                          <div className=\"flex gap-3\">\n                            <Button variant=\"outline\" className=\"flex-1\" onClick={() => setPreviewBaixa(null)}>Recalcular</Button>\n                            <Button className=\"flex-1\" onClick={confirmarBaixa} disabled={loadingBaixa}>\n                              {loadingBaixa ? 'Registrando...' : 'Confirmar Produ\u00e7\u00e3o'}\n                            </Button>\n                          </div>\n                        </>\n                      )}\n                    </>\n                  )}\n                </>\n              ) : (\n                <div className=\"space-y-4\">\n                  <div className=\"flex items-center gap-3 p-4 bg-green-50 rounded-lg border border-green-200\">\n                    <CheckCircle size={20} className=\"text-green-500\" />\n                    <div>\n                      <p className=\"text-sm font-semibold text-green-700\">Produ\u00e7\u00e3o registrada!</p>\n                      <p className=\"text-sm text-green-600\">{resultadoBaixa.message}</p>\n                    </div>\n                  </div>\n                  <Button className=\"w-full\" onClick={fecharBaixa}>Fechar</Button>\n                </div>\n              )}\n            </div>\n          </div>\n        </div>\n      )}\n    </div>\n  )\n}\n"],
  ["app/api/[tenant]/producao/grade/route.ts", "// @ts-nocheck\nimport type { NextRequest } from 'next/server'\nimport { resolveTenant } from '@/lib/auth/tenant'\nimport { pool } from '@/lib/db/connection'\nimport { ok, serverError } from '@/lib/api/responses'\n\ntype Params = { params: { tenant: string } }\n\nexport async function GET(req: NextRequest, { params }: Params) {\n  try {\n    const tenant = await resolveTenant(params.tenant)\n    const { searchParams } = new URL(req.url)\n    // Aceita tanto inicio/fim quanto dataInicio/dataFim para compatibilidade\n    const inicio = searchParams.get('inicio') ?? searchParams.get('dataInicio') ?? new Date().toISOString().slice(0, 10)\n    const fim    = searchParams.get('fim')    ?? searchParams.get('dataFim')    ?? new Date().toISOString().slice(0, 10)\n\n    const client = await pool.connect()\n    try {\n      await client.query(`SET search_path TO \"${tenant.schemaName}\", public`)\n\n      // Produtos ativos\n      const produtosRes = await client.query(`\n        SELECT produto_id, nome, estoque_atual, estoque_minimo, unidade\n        FROM t_produto\n        WHERE active_flg = true\n        ORDER BY nome\n      `)\n\n      // Grade de produ\u00e7\u00e3o da semana\n      const gradeRes = await client.query(`\n        SELECT produto_id, data_producao::text, quantidade\n        FROM t_producao_grade\n        WHERE active_flg = true\n          AND data_producao >= $1::date\n          AND data_producao <= $2::date\n      `, [inicio, fim])\n\n      // Monta grade[produtoId][data] = quantidade\n      const grade: Record<number, Record<string, number>> = {}\n      for (const p of produtosRes.rows) grade[p.produto_id] = {}\n      for (const g of gradeRes.rows) {\n        const data = g.data_producao.slice(0, 10)\n        if (!grade[g.produto_id]) grade[g.produto_id] = {}\n        grade[g.produto_id][data] = Number(g.quantidade)\n      }\n\n      const produtos = produtosRes.rows.map(p => ({\n        produtoId:     p.produto_id,\n        nome:          p.nome,\n        estoqueAtual:  Number(p.estoque_atual ?? 0),\n        estoqueMinimo: Number(p.estoque_minimo ?? 0),\n        unidade:       p.unidade,\n      }))\n\n      // Pedidos da semana (por produto e data de previs\u00e3o de produ\u00e7\u00e3o)\n      const pedidosRes = await client.query(`\n        SELECT pi.produto_id, \n               COALESCE(p.previsao_producao, p.data_pedido)::date as data_ref,\n               SUM(pi.quantidade) as qtd\n        FROM t_pedido_item pi\n        JOIN t_pedido p ON pi.pedido_id = p.pedido_id\n        WHERE p.active_flg = true\n          AND p.status IN ('pendente', 'producao')\n          AND COALESCE(p.previsao_producao, p.data_pedido)::date BETWEEN $1::date AND $2::date\n        GROUP BY pi.produto_id, COALESCE(p.previsao_producao, p.data_pedido)::date\n      `, [inicio, fim]).catch(() => ({ rows: [] }))\n\n      const pedidos: Record<number, Record<string, number>> = {}\n      for (const row of pedidosRes.rows) {\n        const data = row.data_ref instanceof Date ? row.data_ref.toISOString().slice(0, 10) : String(row.data_ref).slice(0, 10)\n        if (!pedidos[row.produto_id]) pedidos[row.produto_id] = {}\n        pedidos[row.produto_id][data] = Number(row.qtd)\n      }\n\n      return ok({ produtos, grade, pedidos, inicio, fim })\n    } finally {\n      client.release()\n    }\n  } catch (err) {\n    return serverError(err)\n  }\n}\n\nexport async function POST(req: NextRequest, { params }: Params) {\n  try {\n    const tenant = await resolveTenant(params.tenant)\n    const body   = await req.json()\n    const { produtoId, dataProducao, quantidade } = body\n\n    if (!produtoId || !dataProducao) {\n      return serverError(new Error('produtoId e dataProducao s\u00e3o obrigat\u00f3rios'))\n    }\n\n    const client = await pool.connect()\n    try {\n      await client.query(`SET search_path TO \"${tenant.schemaName}\", public`)\n\n      if (quantidade === 0) {\n        // Remove a c\u00e9lula se quantidade for zero\n        await client.query(`\n          UPDATE t_producao_grade\n          SET active_flg = false, updated_dt = NOW()\n          WHERE produto_id = $1 AND data_producao = $2::date AND active_flg = true\n        `, [produtoId, dataProducao])\n      } else {\n        // Upsert da c\u00e9lula\n        await client.query(`\n          INSERT INTO t_producao_grade (produto_id, data_producao, quantidade, created_by, updated_by, created_dt, updated_dt, active_flg, modification_num)\n          VALUES ($1, $2::date, $3, 1, 1, NOW(), NOW(), true, 0)\n          ON CONFLICT (produto_id, data_producao)\n          DO UPDATE SET quantidade = $3, updated_dt = NOW(), active_flg = true\n        `, [produtoId, dataProducao, quantidade])\n      }\n\n      return ok({ ok: true, produtoId, dataProducao, quantidade })\n    } finally {\n      client.release()\n    }\n  } catch (err) {\n    return serverError(err)\n  }\n}\n"],
]

for (const [dest, content] of arquivos) {
  fs.mkdirSync(path.dirname(dest), { recursive: true })
  fs.writeFileSync(dest, content, 'utf8')
  const size = fs.statSync(dest).size
  console.log(`OK ${size}b: ${dest}`)
}
console.log('\n✓ Todos os arquivos escritos com sucesso!')